package com.gieligotchi;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(GieligotchiConfig.GROUP)
public interface GieligotchiConfig extends Config
{
	String GROUP = "gieligotchi";

	@ConfigItem(keyName = "showOverlay", name = "Show companion overlay",
		description = "Show the active egg or companion in the game view")
	default boolean showOverlay() { return true; }

	@ConfigItem(keyName = "showBackdropInOverlay", name = "Show backdrop in game overlay",
		description = "Show your equipped cosmetic backdrop in the game overlay; the sidebar always uses it",
		position = 1)
	default boolean showBackdropInOverlay() { return false; }

	@ConfigItem(keyName = "showToyInOverlay", name = "Show toy in game overlay",
		description = "Show your equipped toy in the game overlay; the sidebar always uses it",
		position = 2)
	default boolean showToyInOverlay() { return false; }

	@ConfigItem(keyName = "unlockOverlay", name = "Unlock overlay movement",
		description = "Allow the Gieligotchi overlay to be dragged", position = 3)
	default boolean unlockOverlay() { return false; }

	@Range(min = 50, max = 250)
	@ConfigItem(keyName = "overlayScale", name = "Overlay size",
		description = "Scale the pixel-art overlay from 50% to 250%; 100% is the compact default", position = 4)
	default int overlayScale() { return 100; }

	@Range(min = 100, max = 140)
	@ConfigItem(keyName = "textScale", name = "Text size",
		description = "Scale text throughout the Gieligotchi sidebar and overlay; 120% is the readable default",
		position = 5)
	default int textScale() { return 120; }

	@ConfigItem(keyName = "reducedMotion", name = "Reduced motion",
		description = "Hold the first animation frame and disable wandering", position = 6)
	default boolean reducedMotion() { return false; }

	@ConfigItem(keyName = "resetAccount", name = "Reset Gieligotchi account",
		description = "Permanently erase the current account's eggs, companions, collection, purchases and progress",
		warning = "This permanently erases all Gieligotchi progress for the current account. This cannot be undone.",
		position = 7)
	default boolean resetAccount() { return false; }
}

package com.gieligotchi;

import com.google.inject.Provides;
import com.gieligotchi.model.EggState;
import com.gieligotchi.model.ProfileState;
import com.gieligotchi.model.Toy;
import com.gieligotchi.service.ActivityRewardPolicy;
import com.gieligotchi.service.GieligotchiStateService;
import com.gieligotchi.ui.GieligotchiOverlay;
import com.gieligotchi.ui.GieligotchiPanel;
import com.gieligotchi.ui.HatchAnimationController;
import com.gieligotchi.ui.SpriteAssets;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import javax.inject.Inject;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemID;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Gieligotchi",
	description = "Raise, hatch and collect cosmetic companions through ordinary RuneScape play",
	tags = {"tamagotchi", "pet", "companion", "collection", "cosmetic"}
)
public class GieligotchiPlugin extends Plugin implements MouseListener
{
	@Inject private Client client;
	@Inject private GieligotchiConfig config;
	@Inject private GieligotchiStateService stateService;
	@Inject private GieligotchiPanel panel;
	@Inject private GieligotchiOverlay overlay;
	@Inject private HatchAnimationController hatchAnimation;
	@Inject private OverlayManager overlayManager;
	@Inject private ClientToolbar clientToolbar;
	@Inject private MouseManager mouseManager;
	@Inject private Notifier notifier;
	@Inject private ItemManager itemManager;
	@Inject private ConfigManager configManager;
	@Inject private ChatMessageManager chatMessageManager;
	private NavigationButton navigationButton;
	private String loadedProfileKey;
	private boolean welcomeOpening;
	private boolean skillBaselinesSynchronized;
	private long saveReplacementVersion;
	private int lastRegionId = -1;
	private int lastSlayerCount = -1;
	private final Map<Integer, Integer> engagedNpcTicks = new HashMap<>();
	private final Map<String, Long> recentActivityAwards = new HashMap<>();
	private final Map<Integer, Integer> inventorySnapshot = new HashMap<>();
	private boolean inventorySnapshotReady;
	private final Runnable profileListener = this::onProfileChanged;
	private Point overlayDragOffset;
	private boolean overlayDragged;

	@Provides
	GieligotchiConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GieligotchiConfig.class);
	}

	@Override
	protected void startUp()
	{
		AsyncBufferedImage partyhat = itemManager.getImage(ItemID.RED_PARTYHAT);
		partyhat.onLoaded(() -> SwingUtilities.invokeLater(() ->
		{
			SpriteAssets.setMaxLevelPartyhat(partyhat);
			panel.refresh();
		}));
		loadToyAssets();
		BufferedImage icon = SpriteAssets.egg(com.gieligotchi.model.EggTier.COMMON);
		navigationButton = NavigationButton.builder()
			.tooltip("Gieligotchi")
			.icon(SpriteAssets.resizeNearestShadowedOpaque(icon, 32, 32))
			.priority(7)
			.panel(panel)
			.build();
		panel.startUp();
		clientToolbar.addNavigation(navigationButton);
		overlay.syncMovement();
		overlayManager.add(overlay);
		mouseManager.registerMouseListener(this);
		stateService.addListener(profileListener);
		loadCurrentProfile();
		log.info("Gieligotchi started");
	}

	private void loadToyAssets()
	{
		loadToyAsset(Toy.PLAY_BALL, ItemID.GNOMEBALL);
		loadToyAsset(Toy.DRAGON_PLUSH, ItemID.JAD_PLUSH);
		loadToyAsset(Toy.FEATHER_WAND, ItemID.HAND_FAN);
		int[] runeIds = {
			ItemID.AIR_RUNE, ItemID.WATER_RUNE, ItemID.EARTH_RUNE, ItemID.FIRE_RUNE,
			ItemID.NATURE_RUNE, ItemID.CHAOS_RUNE
		};
		List<AsyncBufferedImage> runes = new ArrayList<>(runeIds.length);
		AtomicInteger waiting = new AtomicInteger(runeIds.length);
		for (int runeId : runeIds)
		{
			AsyncBufferedImage rune = itemManager.getImage(runeId);
			runes.add(rune);
			rune.onLoaded(() ->
			{
				if (waiting.decrementAndGet() == 0)
				{
					SwingUtilities.invokeLater(() ->
					{
						SpriteAssets.setToyImage(Toy.RUNE_BLOCKS, SpriteAssets.composeRunePile(runes));
						panel.refresh();
					});
				}
			});
		}
	}

	private void loadToyAsset(Toy toy, int itemId)
	{
		AsyncBufferedImage image = itemManager.getImage(itemId);
		image.onLoaded(() -> SwingUtilities.invokeLater(() ->
		{
			SpriteAssets.setToyImage(toy, image);
			panel.refresh();
		}));
	}

	@Override
	protected void shutDown()
	{
		stateService.syncNow(null);
		stateService.backup();
		stateService.unload();
		mouseManager.unregisterMouseListener(this);
		stateService.removeListener(profileListener);
		overlayManager.remove(overlay);
		if (navigationButton != null) { clientToolbar.removeNavigation(navigationButton); }
		panel.shutDown();
		loadedProfileKey = null;
		overlayDragOffset = null;
		overlayDragged = false;
		engagedNpcTicks.clear();
		recentActivityAwards.clear();
		inventorySnapshot.clear();
		inventorySnapshotReady = false;
		log.info("Gieligotchi stopped");
	}

	@Subscribe
	public void onConfigSync(net.runelite.client.events.ConfigSync event)
	{
		stateService.syncNow(null);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// LOGGED_IN can arrive before the local player/account hash is ready.
		// Retry cheaply until one profile has actually been selected.
		if (loadedProfileKey == null) { loadCurrentProfile(); }
		if (loadedProfileKey != null && client.getTickCount() % 50 == 0)
		{ stateService.syncNow(configManager.getRSProfileKey()); }
		if (saveReplacementVersion != stateService.getReplacementVersion())
		{
			saveReplacementVersion = stateService.getReplacementVersion();
			skillBaselinesSynchronized = false;
		}
		if (!skillBaselinesSynchronized && stateService.getState() != null)
		{
			Map<Skill, Integer> currentXp = new EnumMap<>(Skill.class);
			for (Skill skill : Skill.values())
			{
				if (skill != Skill.OVERALL) { currentXp.put(skill, client.getSkillExperience(skill)); }
			}
			long reconciledXp = stateService.reconcileLoginXp(currentXp, client.getOverallExperience());
			skillBaselinesSynchronized = true;
			if (reconciledXp > 0)
			{
				queueSystemMessage("Welcome back! You gained " + format(reconciledXp)
					+ " Bonding XP from progress made while you were away.");
				notifyIfReady();
			}
		}
		int currentTick = client.getTickCount();
		engagedNpcTicks.entrySet().removeIf(entry -> currentTick - entry.getValue() > 12);
		recentActivityAwards.entrySet().removeIf(entry -> System.currentTimeMillis() - entry.getValue() > 10_000L);
		if (client.getLocalPlayer() != null)
		{
			int regionId = client.getLocalPlayer().getWorldLocation().getRegionID();
			if (lastRegionId > 0 && regionId != lastRegionId) { stateService.recordRegionVisit(regionId); }
			lastRegionId = regionId;
		}
		int slayerCount = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		if (lastSlayerCount > 0 && slayerCount == 0)
		{
			if (stateService.awardSlayerTask() > 0) { notifyIfReady(); }
		}
		lastSlayerCount = slayerCount;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN) { loadCurrentProfile(); }
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			stateService.syncNow(null);
			stateService.backup();
			stateService.unload();
			loadedProfileKey = null;
			welcomeOpening = false;
			skillBaselinesSynchronized = false;
			lastRegionId = -1;
			lastSlayerCount = -1;
			engagedNpcTicks.clear();
			recentActivityAwards.clear();
			inventorySnapshot.clear();
			inventorySnapshotReady = false;
			hatchAnimation.reset();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (!skillBaselinesSynchronized) { return; }
		net.runelite.api.coords.WorldPoint location = client.getLocalPlayer() == null ? null
			: client.getLocalPlayer().getWorldLocation();
		long award = stateService.observeSkill(event.getSkill(), event.getXp(), client.getOverallExperience(),
			location == null ? -1 : location.getX(), location == null ? -1 : location.getY(),
			location == null ? -1 : location.getPlane());
		if (award > 0) { notifyIfReady(); }
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event == null || event.getItemContainer() == null
			|| event.getContainerId() != InventoryID.INVENTORY.getId()) { return; }
		Map<Integer, Integer> current = new HashMap<>();
		for (Item item : event.getItemContainer().getItems())
		{
			if (item != null && item.getId() >= 0 && item.getQuantity() > 0)
			{ current.merge(item.getId(), item.getQuantity(), Integer::sum); }
		}
		if (!inventorySnapshotReady)
		{
			inventorySnapshot.putAll(current);
			inventorySnapshotReady = true;
			return;
		}
		// Moving an existing item out of the bank is not a fresh acquisition.
		net.runelite.api.widgets.Widget bankItems = client.getWidget(12, 13);
		if (bankItems != null && !bankItems.isHidden())
		{
			inventorySnapshot.clear();
			inventorySnapshot.putAll(current);
			return;
		}
		net.runelite.api.coords.WorldPoint location = client.getLocalPlayer() == null ? null
			: client.getLocalPlayer().getWorldLocation();
		for (Map.Entry<Integer, Integer> entry : current.entrySet())
		{
			int gained = entry.getValue() - inventorySnapshot.getOrDefault(entry.getKey(), 0);
			if (gained > 0)
			{
				stateService.recordHeartfeltItem(entry.getKey(), gained,
					location == null ? -1 : location.getX(), location == null ? -1 : location.getY(),
					location == null ? -1 : location.getPlane());
			}
		}
		inventorySnapshot.clear();
		inventorySnapshot.putAll(current);
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		if (event.getSource() == client.getLocalPlayer() && event.getTarget() instanceof NPC)
		{
			engagedNpcTicks.put(((NPC) event.getTarget()).getIndex(), client.getTickCount());
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Actor actor = event.getActor();
		Hitsplat hitsplat = event.getHitsplat();
		if (actor instanceof NPC && hitsplat != null && hitsplat.isMine())
		{
			engagedNpcTicks.put(((NPC) actor).getIndex(), client.getTickCount());
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!(event.getActor() instanceof NPC)) { return; }
		NPC npc = (NPC) event.getActor();
		Integer engagedAt = engagedNpcTicks.remove(npc.getIndex());
		if (engagedAt == null || client.getTickCount() - engagedAt > 12) { return; }
		long award = stateService.awardNpcKill(npc.getId(), npc.getName(), npc.getCombatLevel());
		if (award > 0) { notifyIfReady(); }
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event == null || (event.getType() != ChatMessageType.GAMEMESSAGE
			&& event.getType() != ChatMessageType.SPAM)) { return; }
		String message = Text.removeTags(event.getMessage());
		stateService.recordSkillingActivity(com.gieligotchi.model.SkillingActivity.match(message));
		ActivityRewardPolicy.Reward reward = ActivityRewardPolicy.match(message);
		if (reward == null) { return; }
		long now = System.currentTimeMillis();
		Long previous = recentActivityAwards.get(reward.getId());
		if (previous != null && now - previous < 2_500L) { return; }
		recentActivityAwards.put(reward.getId(), now);
		long award = stateService.awardActivity(reward.getId(), reward.getLabel(), reward.getAmount());
		if (award > 0)
		{
			log.debug("{} awarded {} Bonding XP", reward.getLabel(), award);
			notifyIfReady();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (GieligotchiConfig.GROUP.equals(event.getGroup()))
		{
			if ("resetAccount".equals(event.getKey()) && config.resetAccount())
			{
				SwingUtilities.invokeLater(this::confirmAccountReset);
				return;
			}
			overlay.syncMovement();
			if (!config.unlockOverlay())
			{
				overlayDragOffset = null;
				overlayDragged = false;
			}
			if ("textScale".equals(event.getKey())) { panel.refresh(); }
		}
	}

	private void confirmAccountReset()
	{
		int choice = JOptionPane.showConfirmDialog(panel,
			"This will permanently erase every Gieligotchi egg, companion, collection entry,\n"
				+ "purchase, memory and point for the current account.\n\nStart over from a new starter egg?",
			"Reset Gieligotchi account", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
		welcomeOpening = false;
		if (choice == JOptionPane.YES_OPTION && stateService.resetProfile())
		{
			hatchAnimation.reset();
			skillBaselinesSynchronized = false;
			lastRegionId = -1;
			lastSlayerCount = -1;
			queueSystemMessage("Your Gieligotchi account has been reset. A new starter egg is waiting for you.");
		}
		configManager.setConfiguration(GieligotchiConfig.GROUP, "resetAccount", false);
	}

	private void queueSystemMessage(String message)
	{
		String plain = "[Gieligotchi] " + message;
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.value(plain)
			.runeLiteFormattedMessage("<col=ffcc66>[Gieligotchi]</col> " + message)
			.build());
	}

	private static String format(long amount)
	{
		return String.format(Locale.UK, "%,d", amount);
	}

	private void loadCurrentProfile()
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null) { return; }
		long accountHash = client.getAccountHash();
		// Wait for the stable character namespace before loading or syncing any save.
		if (accountHash == -1L || accountHash == 0L || configManager.getRSProfileKey() == null) { return; }
		if (configManager.getRSProfiles().stream().noneMatch(profile -> profile.getAccountHash() == accountHash
			&& profile.getKey().equals(configManager.getRSProfileKey()))) { return; }
		String name = client.getLocalPlayer().getName();
		String key = accountHash != -1L && accountHash != 0L
			? "account-" + Long.toUnsignedString(accountHash)
			: "character-" + (name == null ? "unknown" : name.trim().toLowerCase(Locale.ENGLISH));
		if (!key.equals(loadedProfileKey))
		{
			loadedProfileKey = key;
			skillBaselinesSynchronized = false;
			stateService.load(key, configManager.getRSProfileKey());
		}
	}

	private void notifyIfReady()
	{
		ProfileState state = stateService.getState();
		EggState egg = state == null ? null : state.getActiveEgg();
		if (egg != null && egg.isReady() && !egg.isReadyNotificationSent())
		{
			notifier.notify("Your Gieligotchi egg is ready to hatch!");
			stateService.markReadyNotificationSent();
		}
	}

	private void onProfileChanged()
	{
		ProfileState state = stateService.getState();
		if (state == null || state.isWelcomeSeen() || welcomeOpening) { return; }
		welcomeOpening = true;
		SwingUtilities.invokeLater(() ->
		{
			clientToolbar.openPanel(navigationButton);
			panel.showFirstRunWelcome();
		});
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event)
	{
		if (event.getButton() != MouseEvent.BUTTON1 || !config.showOverlay()) { return event; }
		Rectangle bounds = overlay.getBounds();
		if (bounds != null && bounds.contains(event.getPoint()))
		{
			if (hatchAnimation.isCeremonyActive())
			{
				event.consume();
				return event;
			}
			ProfileState state = stateService.getState();
			EggState egg = state == null ? null : state.getActiveEgg();
			if (egg != null && egg.isReady()) { hatchAnimation.beginHatch(); }
			else if (egg != null && !config.unlockOverlay()) { SwingUtilities.invokeLater(panel::inspectActive); }
			else { return event; }
			event.consume();
			return event;
		}
		return event;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent event)
	{
		if (event.getButton() != MouseEvent.BUTTON1 || !config.showOverlay() || !config.unlockOverlay()) { return event; }
		Rectangle bounds = overlay.getBounds();
		if (bounds == null || !bounds.contains(event.getPoint())) { return event; }
		overlayDragOffset = new Point(event.getX() - bounds.x, event.getY() - bounds.y);
		overlayDragged = false;
		event.consume();
		return event;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent event)
	{
		if (overlayDragOffset == null) { return event; }
		overlayDragOffset = null;
		if (overlayDragged) { overlayManager.saveOverlay(overlay); }
		overlayDragged = false;
		event.consume();
		return event;
	}
	@Override public MouseEvent mouseEntered(MouseEvent event) { return event; }
	@Override public MouseEvent mouseExited(MouseEvent event) { overlay.setHovered(false); return event; }
	@Override
	public MouseEvent mouseDragged(MouseEvent event)
	{
		if (overlayDragOffset == null || !config.unlockOverlay())
		{
			updateOverlayHover(event);
			return event;
		}
		Rectangle bounds = overlay.getBounds();
		if (bounds == null) { return event; }
		int maxX = Math.max(0, client.getCanvas().getWidth() - bounds.width);
		int maxY = Math.max(0, client.getCanvas().getHeight() - bounds.height);
		int x = Math.max(0, Math.min(maxX, event.getX() - overlayDragOffset.x));
		int y = Math.max(0, Math.min(maxY, event.getY() - overlayDragOffset.y));
		Point location = new Point(x, y);
		overlay.setPreferredPosition(null);
		overlay.setPreferredLocation(location);
		overlay.setBounds(new Rectangle(location, bounds.getSize()));
		overlayDragged = true;
		overlay.setHovered(true);
		event.consume();
		return event;
	}
	@Override public MouseEvent mouseMoved(MouseEvent event) { updateOverlayHover(event); return event; }

	private void updateOverlayHover(MouseEvent event)
	{
		Rectangle bounds = overlay.getBounds();
		overlay.setHovered(bounds != null && bounds.contains(event.getPoint()));
	}
}

package com.gieligotchi.model;

public enum Backdrop
{
	CLASSIC("Classic LCD", 0),
	LUMBRIDGE("Lumbridge", 150), DRAYNOR_MANOR("Draynor Manor", 200),
	VARROCK("Varrock", 250), FALADOR("Falador", 250),
	ARDOUGNE("Ardougne", 300), RELLEKKA("Rellekka", 300),
	POLLNIVNEACH("Pollnivneach", 300),
	ICE_WOLF_MOUNTAIN("Ice Wolf Mountain", 300),
	TREE_GNOME_STRONGHOLD("Tree Gnome Stronghold", 350),
	GRAND_EXCHANGE("Grand Exchange", 400), MORYTANIA("Morytania", 400),
	WILDERNESS("Wilderness", 450), TZHAAR("TzHaar", 450),
	APE_ATOLL("Ape Atoll", 450), PRIFDDINAS("Prifddinas", 500),
	CIVITAS_ILLA_FORTIS("Civitas illa Fortis", 500), ALDARIN("Aldarin", 500),
	FORTIS_COLOSSEUM("Fortis Colosseum", 750),
	CHAMBERS_OF_XERIC("Chambers of Xeric", 750),
	TOMBS_OF_AMASCUT("Tombs of Amascut", 900),
	THEATRE_OF_BLOOD("Theatre of Blood", 900);

	private final String displayName;
	private final long price;

	Backdrop(String displayName, long price)
	{
		this.displayName = displayName;
		this.price = price;
	}

	public String getDisplayName() { return displayName; }
	public long getPrice() { return price; }
	public String getAssetId() { return name().toLowerCase(); }

	public static Backdrop fromId(String id)
	{
		if (id != null)
		{
			for (Backdrop backdrop : values()) { if (backdrop.getAssetId().equals(id)) { return backdrop; } }
		}
		return CLASSIC;
	}
}

package com.gieligotchi.model;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.UUID;
import com.gieligotchi.service.HeartfeltCatalogue;

public class CompanionInstance
{
	private SkillingGoal megaWish;
	public SkillingGoal getMegaWish() { return megaWish; }
	public boolean startMegaWish(net.runelite.api.Skill skill)
	{
		if (megaWish != null) { return false; }
		megaWish = SkillingGoal.mega(skill);
		return megaWish != null;
	}
	public boolean startMegaWish(SkillingActivity activity)
	{
		if (megaWish != null) { return false; }
		megaWish = SkillingGoal.mega(activity);
		return megaWish != null;
	}
	public long claimMegaWish()
	{
		if (megaWish == null || !megaWish.isComplete()) { return 0; }
		long reward = megaWish.getReward();
		megaWish = null;
		return reward;
	}
	private static final int MAX_WISH_SKIPS = 3;
	private static final long WISH_SKIP_XP = 5_000L;
	private String instanceId;
	private String speciesId;
	private SpeciesRarity speciesRarity;
	private Palette palette;
	private long lifetimeXp;
	private long hatchedAt;
	private EggTier eggTierOrigin;
	private String customName;
	private int affectionHearts;
	private CompanionPersonality personality;
	private Map<String, Integer> personalityPoints = new LinkedHashMap<>();
	private Map<String, Long> skillXpTogether = new LinkedHashMap<>();
	private Map<String, Integer> toyInteractions = new LinkedHashMap<>();
	private List<Integer> regionsVisited = new ArrayList<>();
	private List<MemoryEntry> memories = new ArrayList<>();
	private CompanionWish wish;
	private HeartfeltWish heartfeltWish;
	private int heartfeltCompletions;
	private Integer wishesUntilHeartfelt;
	private List<String> recentHeartfeltTaskIds = new ArrayList<>();
	private boolean lastHeartfeltWasApex;
	private Integer wishSkips;
	private long wishSkipXpRemainder;
	private String favoriteToyId;
	private int highestNpcLevel;
	private String highestNpcName;
	private boolean legacy;
	private long legacyAt;
	private long lastToyPlayedAt;

	public static CompanionInstance from(HatchReceipt receipt)
	{
		CompanionInstance companion = new CompanionInstance();
		companion.instanceId = UUID.randomUUID().toString();
		companion.speciesId = receipt.getSpeciesId();
		companion.speciesRarity = receipt.getSpeciesRarity();
		companion.palette = receipt.getPalette();
		companion.hatchedAt = System.currentTimeMillis();
		companion.eggTierOrigin = receipt.getEggTier();
		companion.memories.add(new MemoryEntry("Hatched", "Began life as a "
			+ receipt.getEggTier().getDisplayName() + " egg"));
		companion.wish = companion.createWish(null, 1);
		companion.wishSkips = MAX_WISH_SKIPS;
		return companion;
	}

	public String getInstanceId() { return instanceId; }
	public String getSpeciesId() { return speciesId; }
	public SpeciesRarity getSpeciesRarity() { return speciesRarity; }
	public Palette getPalette() { return palette; }
	public long getLifetimeXp() { return lifetimeXp; }
	public long getHatchedAt() { return hatchedAt; }
	public EggTier getEggTierOrigin() { return eggTierOrigin; }
	public void addXp(long amount)
	{
		lifetimeXp = Math.max(0, lifetimeXp + amount);
		earnWishSkipProgress(amount);
	}
	public String getCustomName() { return customName; }
	public String getDisplayName(String speciesName) { return customName == null || customName.trim().isEmpty() ? speciesName : customName; }
	public int getAffectionHearts() { return affectionHearts; }
	public RelationshipStage getRelationshipStage() { return RelationshipStage.forHearts(affectionHearts); }
	public CompanionPersonality getPersonality() { return personality; }
	public CompanionWish getWish() { return wish; }
	public HeartfeltWish getHeartfeltWish() { return heartfeltWish; }
	public int getHeartfeltCompletions() { return heartfeltCompletions; }
	public int getWishSkips() { return wishSkips == null ? MAX_WISH_SKIPS : wishSkips; }
	public long getWishSkipXpRemainder() { return wishSkipXpRemainder; }
	public List<MemoryEntry> getMemories() { return memories; }
	public String getFavoriteToyId() { return favoriteToyId; }
	public int getHighestNpcLevel() { return highestNpcLevel; }
	public String getHighestNpcName() { return highestNpcName; }
	public boolean isLegacy() { return legacy; }
	public long getLegacyAt() { return legacyAt; }
	public long getLastToyPlayedAt() { return lastToyPlayedAt; }

	public void repair()
	{
		if (personalityPoints == null) { personalityPoints = new LinkedHashMap<>(); }
		if (skillXpTogether == null) { skillXpTogether = new LinkedHashMap<>(); }
		if (toyInteractions == null) { toyInteractions = new LinkedHashMap<>(); }
		if (regionsVisited == null) { regionsVisited = new ArrayList<>(); }
		if (memories == null) { memories = new ArrayList<>(); }
		if (recentHeartfeltTaskIds == null) { recentHeartfeltTaskIds = new ArrayList<>(); }
		if (heartfeltWish != null) { heartfeltWish.repair(); }
		heartfeltCompletions = Math.max(0, heartfeltCompletions);
		if (wish == null) { wish = createWish(null, 1); }
		if (wishSkips == null) { wishSkips = MAX_WISH_SKIPS; }
		wishSkips = Math.max(0, Math.min(MAX_WISH_SKIPS, wishSkips));
		wishSkipXpRemainder = wishSkips >= MAX_WISH_SKIPS ? 0
			: Math.max(0, Math.min(WISH_SKIP_XP - 1, wishSkipXpRemainder));
	}

	public void rename(String name)
	{
		if (affectionHearts < 5 || name == null) { return; }
		String clean = name.trim().replaceAll("[^A-Za-z0-9 '\\-]", "");
		if (clean.isEmpty()) { return; }
		customName = clean.substring(0, Math.min(18, clean.length()));
		addMemoryOnce("Named", "Became known as " + customName);
	}

	public boolean rerollWish(int companionLevel)
	{
		if (getWishSkips() <= 0) { return false; }
		wishSkips = getWishSkips() - 1;
		wish = createWish(wish == null ? null : wish.getType(), companionLevel);
		return true;
	}
	public boolean rerollWish() { return rerollWish(1); }

	public boolean claimWish(int nextWishLevel)
	{
		if (wish == null || !wish.isComplete()) { return false; }
		CompanionWish.Type completedType = wish.getType();
		affectionHearts = Math.min(100, affectionHearts + 1);
		addPersonalityPoint(personalityFor(completedType), 1);
		addMemoryOnce("Wish fulfilled", wish.getLabel());
		checkRelationshipMilestones();
		wish = createWish(completedType, nextWishLevel);
		return true;
	}
	public boolean claimWish() { return claimWish(1); }

	public boolean considerHeartfeltWish(Map<String, Integer> levels, int totalLevel, Random random)
	{
		if (heartfeltWish != null) { return false; }
		Random rng = random == null ? new Random() : random;
		if (wishesUntilHeartfelt == null) { wishesUntilHeartfelt = 1 + rng.nextInt(5); }
		wishesUntilHeartfelt--;
		if (wishesUntilHeartfelt > 0) { return false; }
		HeartfeltWish candidate = HeartfeltCatalogue.roll(levels, totalLevel, recentHeartfeltTaskIds, rng);
		for (int retry = 0; retry < 6 && candidate != null && candidate.isApex() && lastHeartfeltWasApex; retry++)
		{ candidate = HeartfeltCatalogue.roll(levels, totalLevel, recentHeartfeltTaskIds, rng); }
		heartfeltWish = candidate;
		wishesUntilHeartfelt = 5;
		return heartfeltWish != null;
	}

	public boolean forceHeartfeltWish(HeartfeltWish wish)
	{
		if (wish == null) { return false; }
		heartfeltWish = wish;
		wishesUntilHeartfelt = 5;
		return true;
	}

	public boolean acceptHeartfeltWish()
	{
		if (heartfeltWish == null || heartfeltWish.isAccepted()) { return false; }
		heartfeltWish.accept();
		return true;
	}

	public boolean passHeartfeltWish()
	{
		if (heartfeltWish == null) { return false; }
		rememberHeartfelt(heartfeltWish);
		heartfeltWish = null;
		return true;
	}

	public HeartfeltWish finishHeartfeltWish()
	{
		if (heartfeltWish == null || !heartfeltWish.isComplete()) { return null; }
		HeartfeltWish completed = heartfeltWish;
		heartfeltCompletions++;
		affectionHearts = Math.min(100, affectionHearts + 2);
		addPersonalityPoint(CompanionPersonality.ADVENTUROUS, completed.isApex() ? 4 : 2);
		addMemoryOnce(completed.isApex() ? "Apex wish fulfilled" : "Heartfelt wish fulfilled", completed.getTitle());
		checkRelationshipMilestones();
		rememberHeartfelt(completed);
		heartfeltWish = null;
		return completed;
	}

	public void recordHeartfeltItem(int itemId, long quantity, int x, int y, int plane)
	{ if (heartfeltWish != null) { heartfeltWish.recordItem(itemId, quantity, x, y, plane); } }
	public void recordHeartfeltSkill(String skill, long xp, int x, int y, int plane)
	{ if (heartfeltWish != null) { heartfeltWish.recordSkill(skill, xp, x, y, plane); } }
	public void recordHeartfeltNpc(String npcName)
	{ if (heartfeltWish != null) { heartfeltWish.recordNpc(npcName); } }
	public void recordHeartfeltActivity(String activityId)
	{ if (heartfeltWish != null) { heartfeltWish.recordActivity(activityId); } }

	private void rememberHeartfelt(HeartfeltWish completed)
	{
		if (completed == null) { return; }
		lastHeartfeltWasApex = completed.isApex();
		if (completed.getTaskId() != null)
		{
			recentHeartfeltTaskIds.remove(completed.getTaskId());
			recentHeartfeltTaskIds.add(completed.getTaskId());
			while (recentHeartfeltTaskIds.size() > 10) { recentHeartfeltTaskIds.remove(0); }
		}
	}

	public void recordSkill(String skillName, long rawXp)
	{
		if (rawXp <= 0) { return; }
		skillXpTogether.merge(skillName, rawXp, Long::sum);
		addPersonalityPoint(CompanionPersonality.INDUSTRIOUS, rawXp >= 5_000 ? 1 : 0);
		progressWish(CompanionWish.Type.SKILLING, rawXp);
	}

	public void recordNpcKill(String npcName, int combatLevel)
	{
		int level = Math.max(1, combatLevel);
		addPersonalityPoint(CompanionPersonality.FIERCE, level >= 50 ? 2 : 1);
		progressWish(CompanionWish.Type.COMBAT, level);
		if (level > highestNpcLevel)
		{
			highestNpcLevel = level;
			highestNpcName = npcName == null ? "Unknown foe" : npcName;
			addMemoryOnce("Strongest foe", highestNpcName + " (level " + level + ")");
		}
	}

	public void recordQuestOrClue(String label)
	{
		addPersonalityPoint(CompanionPersonality.ADVENTUROUS, 2);
		progressWish(CompanionWish.Type.ADVENTURE, 1);
		if (label != null && !label.isEmpty()) { addMemoryOnce("Adventure", label); }
	}

	public void recordSlayerTask()
	{
		addPersonalityPoint(CompanionPersonality.FIERCE, 2);
		progressWish(CompanionWish.Type.SLAYER, 1);
		addMemoryOnce("Slayer", "Completed a Slayer task together");
	}

	public void recordMajorChallenge(String label)
	{
		addPersonalityPoint(CompanionPersonality.ADVENTUROUS, 2);
		progressWish(CompanionWish.Type.CHALLENGE, 1);
		if (label != null && !label.isEmpty()) { addMemoryOnce("Major challenge", label); }
	}

	public void recordRegionVisit(int regionId)
	{
		if (regionId <= 0 || regionsVisited.contains(regionId)) { return; }
		regionsVisited.add(regionId);
		addPersonalityPoint(CompanionPersonality.ADVENTUROUS, 1);
		progressWish(CompanionWish.Type.EXPLORATION, 1);
		if (regionsVisited.size() % 10 == 0)
		{
			addMemoryOnce("Explorer", "Visited " + regionsVisited.size() + " regions together");
		}
	}

	public void recordGame(boolean won)
	{
		addPersonalityPoint(CompanionPersonality.PLAYFUL, won ? 2 : 1);
		progressWish(CompanionWish.Type.PLAY, won ? 1 : 0);
	}

	public void playWithToy(Toy toy)
	{
		if (toy == null) { return; }
		lastToyPlayedAt = System.currentTimeMillis();
		addPersonalityPoint(toy.getAffinity(), 1);
		int uses = toyInteractions.merge(toy.getAssetId(), 1, Integer::sum);
		if (affectionHearts >= 30 && favoriteToyId == null && uses >= 3)
		{
			favoriteToyId = toy.getAssetId();
			addMemoryOnce("Favourite toy", "Discovered a love for the " + toy.getDisplayName());
		}
	}

	public void recordLevel99()
	{
		addMemoryOnce("Level 99", "Reached the highest companion level");
		if (!legacy)
		{
			legacy = true;
			legacyAt = System.currentTimeMillis();
			addMemoryOnce("Legacy companion", "A lifelong journey was commemorated");
		}
	}

	public String getFavoriteSkill()
	{
		String result = null;
		long best = -1;
		for (Map.Entry<String, Long> entry : skillXpTogether.entrySet())
		{
			if (entry.getValue() > best) { result = entry.getKey(); best = entry.getValue(); }
		}
		return result;
	}

	private void progressWish(CompanionWish.Type type, long amount)
	{
		if (heartfeltWish == null && wish != null && wish.getType() == type && !wish.isComplete()) { wish.addProgress(amount); }
	}

	private void earnWishSkipProgress(long bondingXp)
	{
		if (bondingXp <= 0 || getWishSkips() >= MAX_WISH_SKIPS)
		{
			if (getWishSkips() >= MAX_WISH_SKIPS) { wishSkipXpRemainder = 0; }
			return;
		}
		wishSkipXpRemainder += bondingXp;
		long earned = wishSkipXpRemainder / WISH_SKIP_XP;
		if (earned <= 0) { return; }
		wishSkips = (int) Math.min(MAX_WISH_SKIPS, getWishSkips() + earned);
		wishSkipXpRemainder = getWishSkips() >= MAX_WISH_SKIPS ? 0 : wishSkipXpRemainder % WISH_SKIP_XP;
	}

	private void addPersonalityPoint(CompanionPersonality candidate, int amount)
	{
		if (amount > 0) { personalityPoints.merge(candidate.name(), amount, Integer::sum); }
		if (personality == null && affectionHearts >= 15)
		{
			CompanionPersonality best = CompanionPersonality.LOYAL;
			int bestScore = -1;
			boolean tie = false;
			for (CompanionPersonality value : CompanionPersonality.values())
			{
				int score = personalityPoints.getOrDefault(value.name(), 0);
				if (score > bestScore) { best = value; bestScore = score; tie = false; }
				else if (score == bestScore) { tie = true; }
			}
			personality = tie ? CompanionPersonality.LOYAL : best;
			addMemoryOnce("Personality revealed", personality.getDisplayName());
		}
	}

	private CompanionWish createWish(CompanionWish.Type avoid, int companionLevel)
	{
		long seed = System.nanoTime() ^ (instanceId == null ? 0 : instanceId.hashCode()) ^ affectionHearts;
		Random random = new Random(seed);
		CompanionWish.Type[] types = CompanionWish.Type.values();
		CompanionWish.Type type;
		if (personality != null && random.nextInt(100) < 55) { type = typeFor(personality); }
		else { type = types[random.nextInt(types.length)]; }
		if (type == avoid) { type = types[(type.ordinal() + 1 + random.nextInt(types.length - 1)) % types.length]; }
		return CompanionWish.forLevel(type, companionLevel);
	}

	private void checkRelationshipMilestones()
	{
		RelationshipStage stage = getRelationshipStage();
		if (stage != RelationshipStage.NEWLY_HATCHED)
		{
			addMemoryOnce(stage.getDisplayName(), "Reached " + stage.getHearts() + " affection hearts");
		}
		if (affectionHearts >= 15) { addPersonalityPoint(CompanionPersonality.LOYAL, 0); }
	}

	private void addMemoryOnce(String title, String detail)
	{
		for (MemoryEntry memory : memories)
		{
			if (title.equals(memory.getTitle()) && detail.equals(memory.getDetail())) { return; }
		}
		memories.add(new MemoryEntry(title, detail));
	}

	private static CompanionPersonality personalityFor(CompanionWish.Type type)
	{
		switch (type)
		{
			case COMBAT: return CompanionPersonality.FIERCE;
			case SKILLING: return CompanionPersonality.INDUSTRIOUS;
			case SLAYER: return CompanionPersonality.FIERCE;
			case ADVENTURE: return CompanionPersonality.ADVENTUROUS;
			case CHALLENGE: return CompanionPersonality.ADVENTUROUS;
			case EXPLORATION: return CompanionPersonality.ADVENTUROUS;
			default: return CompanionPersonality.PLAYFUL;
		}
	}

	private static CompanionWish.Type typeFor(CompanionPersonality personality)
	{
		switch (personality)
		{
			case FIERCE: return CompanionWish.Type.COMBAT;
			case INDUSTRIOUS: return CompanionWish.Type.SKILLING;
			case ADVENTUROUS: return CompanionWish.Type.ADVENTURE;
			default: return CompanionWish.Type.PLAY;
		}
	}
}

package com.gieligotchi.model;

public enum CompanionPersonality
{
	FIERCE("Fierce", "Thrives on combat and worthy foes"),
	INDUSTRIOUS("Industrious", "Finds joy in steady skilling"),
	ADVENTUROUS("Adventurous", "Lives for quests and discoveries"),
	PLAYFUL("Playful", "Loves toys and handheld games"),
	LOYAL("Loyal", "Values a balanced life together");

	private final String displayName;
	private final String description;

	CompanionPersonality(String displayName, String description)
	{
		this.displayName = displayName;
		this.description = description;
	}

	public String getDisplayName() { return displayName; }
	public String getDescription() { return description; }
}

package com.gieligotchi.model;

public class CompanionWish
{
	public enum Type { COMBAT, SKILLING, SLAYER, ADVENTURE, CHALLENGE, EXPLORATION, PLAY }
	private static final int MAX_LEVEL = 99;

	private Type type;
	private String label;
	private long target;
	private long progress;

	public CompanionWish(Type type, String label, long target)
	{
		this.type = type;
		this.label = label;
		this.target = Math.max(1, target);
	}

	public static CompanionWish forLevel(Type type, int companionLevel)
	{
		int level = clampLevel(companionLevel);
		switch (type)
		{
			case COMBAT:
				long combatTarget = 80L + (level - 1L) * 4L;
				return new CompanionWish(type, "Defeat foes worth " + combatTarget + " combat levels", combatTarget);
			case SKILLING:
				long xpTarget = 4_000L + (level - 1L) * 250L;
				return new CompanionWish(type, "Earn " + xpTarget + " XP", xpTarget);
			case SLAYER:
				long taskTarget = 1L + (level - 1L) / 50L;
				return new CompanionWish(type, taskTarget == 1 ? "Complete a Slayer task"
					: "Complete " + taskTarget + " Slayer tasks", taskTarget);
			case ADVENTURE:
				return new CompanionWish(type, "Complete a quest or clue", 1);
			case CHALLENGE:
				return new CompanionWish(type, "Complete a raid, Gauntlet or Barbarian Assault Wave 10", 1);
			case EXPLORATION:
				long areaTarget = 1L + (level - 1L) / 40L;
				return new CompanionWish(type, areaTarget == 1 ? "Visit a new area"
					: "Visit " + areaTarget + " new areas", areaTarget);
			case PLAY:
			default:
				long winsTarget = 1L + (level - 1L) / 33L;
				return new CompanionWish(type, winsTarget == 1 ? "Win a round of Higher or Lower"
					: "Win " + winsTarget + " rounds of Higher or Lower", winsTarget);
		}
	}

	public static long rewardXp(Type type, int companionLevel)
	{
		long base;
		switch (type)
		{
			case CHALLENGE: base = 15_000L; break;
			case ADVENTURE: base = 4_000L; break;
			case SLAYER: base = 3_000L; break;
			case COMBAT:
			case SKILLING: base = 1_500L; break;
			case EXPLORATION: base = 1_000L; break;
			case PLAY:
			default: base = 500L; break;
		}
		double multiplier = 1d + 4d * (clampLevel(companionLevel) - 1d) / (MAX_LEVEL - 1d);
		return Math.round(base * multiplier / 100d) * 100L;
	}

	public Type getType() { return type; }
	public String getLabel() { return label; }
	public long getTarget() { return target; }
	public long getProgress() { return progress; }
	public boolean isComplete() { return progress >= target; }
	public void addProgress(long amount) { progress = Math.min(target, progress + Math.max(0, amount)); }

	private static int clampLevel(int level)
	{
		return Math.max(1, Math.min(MAX_LEVEL, level));
	}
}

package com.gieligotchi.model;

