package com.gieligotchi.service;

import com.google.gson.Gson;
import com.gieligotchi.model.ProfileState;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

@Slf4j
@Singleton
public class ProfileStore
{
	private final Gson gson;
	private final java.util.concurrent.Executor executor;
	private final Path directory;
	private final Object fileLock = new Object();
	private String deviceId;

	@Inject
	public ProfileStore(Gson gson, ScheduledExecutorService executor)
	{
		this.gson = gson.newBuilder().setPrettyPrinting().create();
		this.executor = new SerialTasks(executor);
		this.directory = RuneLite.RUNELITE_DIR.toPath().resolve("gieligotchi")
			.resolve(Boolean.getBoolean("gieligotchi.devTools") ? "profiles-dev" : "profiles");
	}

	ProfileStore(Gson gson, ScheduledExecutorService executor, Path directory)
	{
		this.gson = gson.newBuilder().setPrettyPrinting().create();
		this.executor = new SerialTasks(executor);
		this.directory = directory;
	}

	public void load(String profileKey, Consumer<ProfileState> callback)
	{
		executor.execute(() ->
		{
			ProfileState state;
			Path file = fileFor(profileKey);
			try
			{
				synchronized (fileLock)
				{
					state = loadWithBackup(profileKey, file);
				}
				if (state == null) { state = ProfileState.fresh(profileKey); }
				state.repair();
			}
			catch (Exception error)
			{
				log.debug("Unable to load Gieligotchi profile {}", profileKey, error);
				state = ProfileState.fresh(profileKey);
			}
			callback.accept(state);
		});
	}

	public void save(String profileKey, ProfileState state)
	{
		String snapshot = gson.toJson(state);
		writeAsync(profileKey, fileFor(profileKey), snapshot, "save");
	}

	public boolean exists(String key)
	{
		return Files.exists(fileFor(key)) || Files.exists(backupFileFor(key));
	}

	public String deviceId() throws IOException
	{
		synchronized (fileLock)
		{
			if (deviceId == null)
			{
				Path path = directory.resolve("device-id.txt");
				if (Files.exists(path))
				{
					deviceId = java.util.UUID.fromString(Files.readString(path).trim()).toString();
				}
				else
				{
					deviceId = java.util.UUID.randomUUID().toString();
					write(path, deviceId);
				}
			}
			return deviceId;
		}
	}

	/** Recovery files are never overwritten by routine logout backups. */
	public Path archive(ProfileState state) throws IOException
	{
		synchronized (fileLock)
		{
			Path path = directory.resolve("recovery-" + java.util.UUID.randomUUID() + ".json");
			write(path, gson.toJson(state));
			return path;
		}
	}

	public Path getDirectory() { return directory; }

	public void backup(String profileKey, ProfileState state)
	{
		if (profileKey == null || state == null) { return; }
		String snapshot = gson.toJson(state);
		writeAsync(profileKey, backupFileFor(profileKey), snapshot, "back up");
	}

	public void reset(String profileKey, ProfileState state)
	{
		if (profileKey == null || state == null) { return; }
		String snapshot = gson.toJson(state);
		writeAsync(profileKey, fileFor(profileKey), snapshot, "reset");
		writeAsync(profileKey, backupFileFor(profileKey), snapshot, "reset backup");
	}

	private ProfileState loadWithBackup(String profileKey, Path file) throws IOException
	{
		if (Files.isRegularFile(file))
		{
			try { return read(file); }
			catch (Exception error)
			{
				log.debug("Unable to read Gieligotchi profile {}; trying backup", profileKey, error);
			}
		}
		Path backup = backupFileFor(profileKey);
		if (Files.isRegularFile(backup)) { return read(backup); }
		return ProfileState.fresh(profileKey);
	}

	private ProfileState read(Path file) throws IOException
	{
		try (Reader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8))
		{
			return gson.fromJson(reader, ProfileState.class);
		}
	}

	private void writeAsync(String profileKey, Path file, String snapshot, String operation)
	{
		executor.execute(() ->
		{
			try
			{
				synchronized (fileLock)
				{
					write(file, snapshot);
				}
			}
			catch (IOException error)
			{
				log.debug("Unable to {} Gieligotchi profile {}", operation, profileKey, error);
			}
		});
	}

	private void write(Path file, String snapshot) throws IOException
	{
		Path temporary = file.resolveSibling(file.getFileName() + ".tmp");
		Files.createDirectories(directory);
		try (Writer writer = Files.newBufferedWriter(temporary, StandardCharsets.UTF_8))
		{
			writer.write(snapshot);
		}
		try
		{
			Files.move(temporary, file, StandardCopyOption.REPLACE_EXISTING,
				StandardCopyOption.ATOMIC_MOVE);
		}
		catch (IOException atomicNotSupported)
		{
			Files.move(temporary, file, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	private Path fileFor(String profileKey)
	{
		String safe = profileKey.replaceAll("[^A-Za-z0-9_-]", "_");
		return directory.resolve(safe + ".json");
	}

	private Path backupFileFor(String profileKey)
	{
		String safe = profileKey.replaceAll("[^A-Za-z0-9_-]", "_");
		return directory.resolve(safe + ".backup.json");
	}

	/** Keep disk loads and writes in request order even on RuneLite's shared thread pool. */
	private static final class SerialTasks implements java.util.concurrent.Executor
	{
		private final java.util.concurrent.Executor delegate;
		private final java.util.Queue<Runnable> tasks = new java.util.ArrayDeque<>();
		private boolean running;
		private SerialTasks(java.util.concurrent.Executor delegate) { this.delegate = delegate; }
		@Override public synchronized void execute(Runnable task)
		{
			tasks.add(task);
			if (!running)
			{
				running = true;
				try { delegate.execute(this::drain); }
				catch (RuntimeException error) { running = false; tasks.remove(task); throw error; }
			}
		}
		private void drain()
		{
			while (true)
			{
				Runnable next;
				synchronized (this)
				{
					next = tasks.poll();
					if (next == null) { running = false; return; }
				}
				try { next.run(); }
				catch (RuntimeException error) { log.warn("Gieligotchi save operation failed", error); }
			}
		}
	}
}

package com.gieligotchi.service;

import com.gieligotchi.model.ProfileState;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/** Each device owns a separate configuration key, so offline writers cannot erase each other. */
@Singleton
public class ProfileSync
{
	private static final String GROUP = "gieligotchisaves";
	private static final String PREFIX = "device";
	@Inject private ConfigManager config;
	@Inject private SaveCodec codec;

	public String unavailable(String rsProfile)
	{
		if (Boolean.getBoolean("gieligotchi.devTools")) { return "Test client: cloud sync isolated. Export/import available."; }
		if (rsProfile == null) { return "Waiting for RuneLite character profile."; }
		return null;
	}

	public List<ProfileState> read(String rsProfile, String character) throws IOException
	{
		List<ProfileState> snapshots = new ArrayList<>();
		List<String> keys = config.getRSProfileConfigurationKeys(GROUP, rsProfile, PREFIX);
		java.util.Collections.sort(keys);
		if (keys.size() > 16) { throw new IOException("Too many device snapshots. Use Export/Import."); }
		for (String key : keys)
		{
			ProfileState snapshot = codec.unpack(config.getConfiguration(GROUP, rsProfile, key), character);
			if (snapshot.getSaveVersions().isEmpty()) { throw new IOException("Incomplete synced save; keeping local progress."); }
			snapshots.add(snapshot);
		}
		return snapshots;
	}

	public void publish(String rsProfile, String device, ProfileState state) throws IOException
	{
		String key = PREFIX + device.replace("-", "");
		List<String> keys = config.getRSProfileConfigurationKeys(GROUP, rsProfile, PREFIX);
		if (keys.size() >= 16 && !keys.contains(key)) { throw new IOException("Device limit reached. Use Export/Import."); }
		String packed = codec.pack(state);
		if (!packed.equals(config.getConfiguration(GROUP, rsProfile, key)))
		{
			config.setConfiguration(GROUP, rsProfile, key, packed);
		}
	}
}

package com.gieligotchi.service;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/** Difficulty-scaled quest rewards backed by a bundled OSRS Wiki snapshot. */
public final class QuestRewardPolicy
{
	private static final String COMPLETION_PREFIX = "Congratulations, you've completed a quest:";
	private static final String RESOURCE = "/com/gieligotchi/data/quest_difficulties.tsv";
	private static final Map<String, String> DIFFICULTIES = loadDifficulties();

	private QuestRewardPolicy() {}

	public static QuestReward match(String message)
	{
		if (message == null || !message.startsWith(COMPLETION_PREFIX)) { return null; }
		String questName = message.substring(COMPLETION_PREFIX.length()).trim();
		String difficulty = DIFFICULTIES.get(normalize(questName));
		if (difficulty == null) { difficulty = "Experienced"; }
		return new QuestReward(questName, difficulty, amountForDifficulty(difficulty));
	}

	public static long amountForDifficulty(String difficulty)
	{
		if (difficulty == null) { return 5_000L; }
		switch (difficulty.toLowerCase(Locale.ENGLISH))
		{
			case "novice": return 1_500L;
			case "intermediate": return 3_000L;
			case "master": return 10_000L;
			case "grandmaster": return 20_000L;
			case "special":
			case "experienced":
			default: return 5_000L;
		}
	}

	private static Map<String, String> loadDifficulties()
	{
		InputStream stream = QuestRewardPolicy.class.getResourceAsStream(RESOURCE);
		if (stream == null) { return Collections.emptyMap(); }
		Map<String, String> result = new HashMap<>();
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#")) { continue; }
				String[] fields = line.split("\\t", 2);
				if (fields.length == 2) { result.put(normalize(fields[0]), fields[1].trim()); }
			}
		}
		catch (IOException ignored)
		{
			return Collections.emptyMap();
		}
		return Collections.unmodifiableMap(result);
	}

	private static String normalize(String name)
	{
		return name == null ? "" : name.trim().toLowerCase(Locale.ENGLISH)
			.replace('\u2019', '\'').replace('\u2018', '\'').replace('\u2013', '-');
	}

	public static final class QuestReward
	{
		private final String questName;
		private final String difficulty;
		private final long amount;

		private QuestReward(String questName, String difficulty, long amount)
		{
			this.questName = questName;
			this.difficulty = difficulty;
			this.amount = amount;
		}

		public String getQuestName() { return questName; }
		public String getDifficulty() { return difficulty; }
		public long getAmount() { return amount; }
	}
}

package com.gieligotchi.service;

import com.gieligotchi.model.ProfileState;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.Map;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Versioned, bounded transfer format; the entire collection travels together. */
@Singleton
public final class SaveCodec
{
	public static final int MAX_FILE_BYTES = 8 * 1024 * 1024;
	// Deliberately conservative plugin budget, not a claim about the server's quota.
	public static final int MAX_SYNC_CHARS = 16 * 1024;
	private final Gson gson;
	@Inject
	public SaveCodec(Gson gson) { this.gson = gson; }

	public String json(ProfileState state) { return gson.toJson(state); }

	public ProfileState read(String text, String character)
	{
		if (text == null || text.length() > MAX_FILE_BYTES) { throw new IllegalArgumentException("Save is too large."); }
		try
		{
			JsonObject object = gson.fromJson(text, JsonObject.class);
			if (object == null || !object.has("schemaVersion") || object.get("schemaVersion").getAsInt() != 1
				|| !object.has("profileKey") || !character.equals(object.get("profileKey").getAsString()))
			{
				throw new IllegalArgumentException("This save belongs to a different character or a newer plugin version.");
			}
			if (!object.has("starterEggGranted") || !object.has("hatchHistory") || !object.has("discoveries"))
			{
				throw new IllegalArgumentException("This is not a complete Gieligotchi save.");
			}
			ProfileState state = gson.fromJson(object, ProfileState.class);
			if (state.getSaveVersions().size() > 256) { throw new IllegalArgumentException("Invalid save history."); }
			for (Map.Entry<String, Long> entry : state.getSaveVersions().entrySet())
			{
				if (!entry.getKey().matches("[a-f0-9-]{36}") || entry.getValue() == null || entry.getValue() < 0
					|| entry.getValue() == Long.MAX_VALUE) { throw new IllegalArgumentException("Invalid save history."); }
			}
			state.repair();
			return state;
		}
		catch (RuntimeException error)
		{
			throw new IllegalArgumentException("Cannot read this save. Check the character and file version.", error);
		}
	}

	public String pack(ProfileState state) throws IOException
	{
		byte[] json = json(state).getBytes(StandardCharsets.UTF_8);
		if (json.length > MAX_FILE_BYTES) { throw new IOException("Save is too large for sync; use Export."); }
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (GZIPOutputStream gzip = new GZIPOutputStream(bytes)) { gzip.write(json); }
		String packed = "v1:" + Base64.getEncoder().encodeToString(bytes.toByteArray());
		if (packed.length() > MAX_SYNC_CHARS) { throw new IOException("Save exceeds the sync budget. Use Export to move the full collection."); }
		return packed;
	}

	public ProfileState unpack(String packed, String character) throws IOException
	{
		if (packed == null || !packed.startsWith("v1:") || packed.length() > MAX_SYNC_CHARS)
		{ throw new IOException("Unsupported synced save."); }
		try (GZIPInputStream gzip = new GZIPInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(packed.substring(3)))))
		{
			ByteArrayOutputStream bytes = new ByteArrayOutputStream();
			byte[] buffer = new byte[4096];
			int count;
			while ((count = gzip.read(buffer)) != -1)
			{
				if (bytes.size() + count > MAX_FILE_BYTES) { throw new IOException("Synced save expands beyond the safety limit."); }
				bytes.write(buffer, 0, count);
			}
			return read(new String(bytes.toByteArray(), StandardCharsets.UTF_8), character);
		}
		catch (IllegalArgumentException error) { throw new IOException("Invalid synced save.", error); }
	}

	public static boolean dominates(ProfileState newer, ProfileState older)
	{
		for (Map.Entry<String, Long> entry : older.getSaveVersions().entrySet())
		{
			if (newer.getSaveVersions().getOrDefault(entry.getKey(), 0L) < entry.getValue()) { return false; }
		}
		return !newer.getSaveVersions().equals(older.getSaveVersions());
	}

	public static void acknowledge(ProfileState selected, ProfileState other)
	{
		other.getSaveVersions().forEach((key, value) -> selected.getSaveVersions().merge(key, value, Math::max));
	}
}

package com.gieligotchi.service;

import com.gieligotchi.model.ProfileState;
import java.util.Map;
import net.runelite.api.Experience;
import net.runelite.api.Skill;

public final class SkillRewardPolicy
{
	/** A background contribution: one Bonding XP per 5 RuneScape XP. */
	private static final int BONDING_UNITS_PER_OSRS_XP = 1;
	private static final int BONDING_UNIT_SCALE = 5;

	private SkillRewardPolicy() {}

	public static long npcKillAward(int combatLevel)
	{
		return Math.min(Math.max(0, combatLevel) * 5L, 400L);
	}

	public static long observe(ProfileState state, Skill skill, int xp)
	{
		if (state == null || skill == Skill.OVERALL || xp < 0) { return 0; }
		Map<String, Integer> baselines = state.getSkillBaselines();
		String key = skill.name();
		Integer previous = baselines.get(key);
		if (previous == null)
		{
			baselines.put(key, xp);
			state.getSkillLevelBaselines().put(key, levelForXp(xp));
			return 0;
		}
		if (xp <= previous) { return 0; }
		baselines.put(key, xp);
		int delta = xp - previous;
		int accumulatedUnits = state.getSkillRemainders().getOrDefault(key, 0)
			+ delta * BONDING_UNITS_PER_OSRS_XP;
		long award = accumulatedUnits / BONDING_UNIT_SCALE;
		state.getSkillRemainders().put(key, accumulatedUnits % BONDING_UNIT_SCALE);

		int previousLevel = state.getSkillLevelBaselines().getOrDefault(key, levelForXp(previous));
		int currentLevel = levelForXp(xp);
		for (int level = previousLevel + 1; level <= currentLevel; level++)
		{
			award += levelUpAward(level);
		}
		state.getSkillLevelBaselines().put(key, currentLevel);
		return award;
	}

	public static int levelUpAward(int level)
	{
		int clamped = Math.max(1, Math.min(Experience.MAX_VIRT_LEVEL, level));
		if (clamped <= 2) { return 1_250; }
		if (clamped >= Experience.MAX_REAL_LEVEL) { return 35_000; }
		if (clamped <= 20) { return interpolate(clamped, 2, 1_250, 20, 1_800); }
		if (clamped <= 40) { return interpolate(clamped, 20, 1_800, 40, 3_000); }
		if (clamped <= 60) { return interpolate(clamped, 40, 3_000, 60, 5_000); }
		if (clamped <= 80) { return interpolate(clamped, 60, 5_000, 80, 10_000); }
		return interpolate(clamped, 80, 10_000, 99, 35_000);
	}

	private static int interpolate(int level, int fromLevel, int fromAward, int toLevel, int toAward)
	{
		double progress = (level - fromLevel) / (double) (toLevel - fromLevel);
		return (int) (Math.round((fromAward + (toAward - fromAward) * progress) / 100d) * 100L);
	}

	public static int levelForXp(int xp)
	{
		return Math.max(1, Math.min(Experience.MAX_VIRT_LEVEL, Experience.getLevelForXp(Math.max(0, xp))));
	}
}

package com.gieligotchi.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Stroke;
import javax.inject.Singleton;

@Singleton
public class CompanionEffectController
{
	public enum Effect { HEARTS, CORRECT, CELEBRATE, WISH, LEVEL_UP, MAX_LEVEL }

	private volatile Effect effect;
	private volatile long startedAt;

	public void trigger(Effect effect)
	{
		this.effect = effect;
		this.startedAt = System.currentTimeMillis();
	}

	public void render(Graphics2D graphics, int x, int y, int width, int height, double scale)
	{
		Effect current = effect;
		if (current == null) { return; }
		long elapsed = System.currentTimeMillis() - startedAt;
		long duration = current == Effect.MAX_LEVEL ? 4_600L
			: current == Effect.CELEBRATE ? 2_800L
			: current == Effect.LEVEL_UP ? 2_200L : 2_000L;
		if (elapsed < 0 || elapsed >= duration) { return; }
		double life = elapsed / (double) duration;
		if (current == Effect.MAX_LEVEL)
		{
			renderMaxLevel(graphics, x, y, width, height, scale, life);
			return;
		}
		if (current == Effect.LEVEL_UP)
		{
			renderLevelUp(graphics, x, y, width, height, scale, life);
			return;
		}
		int count = current == Effect.CELEBRATE ? 18 : current == Effect.CORRECT ? 8 : 7;
		for (int i = 0; i < count; i++)
		{
			double phase = (life + i * 0.113) % 1d;
			int alpha = Math.max(0, Math.min(255, (int) Math.round(255 * (1d - phase))));
			double wave = Math.sin(i * 2.17 + life * 5d);
			int px = x + width / 2 + (int) Math.round(wave * width * (0.20 + (i % 3) * 0.05));
			int py = y + height - (int) Math.round(phase * height * 0.92) - (i % 2) * 4;
			if (current == Effect.CELEBRATE)
			{
				Color[] colours = {new Color(0xF2C45A), new Color(0xDB85A9), new Color(0x63B7D5), new Color(0x7CB06B)};
				Color colour = colours[i % colours.length];
				graphics.setColor(new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), alpha));
				int size = Math.max(2, (int) Math.round((3 + i % 3) * scale));
				graphics.fillRect(px, py, size, Math.max(2, size / 2));
			}
			else
			{
				String glyph = current == Effect.CORRECT ? "✦" : i % 3 == 0 ? "✦" : "♥";
				Color colour = current == Effect.CORRECT ? new Color(0xF2C45A) : new Color(0xE77989);
				graphics.setColor(new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), alpha));
				graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, Math.max(8, (int) Math.round((10 + i % 3 * 2) * scale))));
				graphics.drawString(glyph, px, py);
			}
		}
	}

	private void renderLevelUp(Graphics2D graphics, int x, int y, int width, int height,
		double scale, double life)
	{
		Color[] colours = {new Color(0xFFF0A6), new Color(0xF2C45A), new Color(0xFFFFFF)};
		int bursts = 2;
		int rays = 9;
		Stroke oldStroke = graphics.getStroke();
		for (int burst = 0; burst < bursts; burst++)
		{
			double local = life * 1.45 - burst * 0.17;
			if (local < 0 || local > 1) { continue; }
			int centreX = x + width / 2 + (int) Math.round(Math.sin(burst * 2.4) * width * 0.18);
			int centreY = y + (int) Math.round(height * (0.30 + (burst % 3) * 0.18));
			double radius = (10 + local * 28) * scale;
			int alpha = Math.max(0, Math.min(255, (int) Math.round(245 * (1 - local))));
			graphics.setStroke(new BasicStroke(Math.max(1f, (float) (1.7 * scale))));
			for (int ray = 0; ray < rays; ray++)
			{
				double angle = Math.PI * 2 * ray / rays + burst * 0.61;
				double inner = radius * 0.46;
				Color colour = colours[(burst + ray) % colours.length];
				graphics.setColor(new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), alpha));
				graphics.drawLine(centreX + (int) Math.round(Math.cos(angle) * inner),
					centreY + (int) Math.round(Math.sin(angle) * inner),
					centreX + (int) Math.round(Math.cos(angle) * radius),
					centreY + (int) Math.round(Math.sin(angle) * radius));
			}
		}

		int sparkCount = 10;
		for (int i = 0; i < sparkCount; i++)
		{
			double phase = (life * 1.25 + i * 0.087) % 1d;
			int alpha = Math.max(0, (int) Math.round(220 * (1 - phase)));
			int px = x + (int) Math.round(width * (0.08 + ((i * 37) % 85) / 100d));
			int py = y + height - (int) Math.round(phase * height * 0.95);
			Color colour = colours[i % colours.length];
			graphics.setColor(new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), alpha));
			int size = Math.max(2, (int) Math.round(3 * scale));
			graphics.fillOval(px, py, size, size);
		}
		graphics.setStroke(oldStroke);
	}

	private void renderMaxLevel(Graphics2D graphics, int x, int y, int width, int height,
		double scale, double life)
	{
		Stroke oldStroke = graphics.getStroke();
		int centreX = x + width / 2;
		int centreY = y + (int) Math.round(height * 0.53);
		double fadeIn = Math.min(1d, life * 8d);
		double fadeOut = Math.min(1d, (1d - life) * 3d);
		int alpha = Math.max(0, Math.min(170, (int) Math.round(170 * fadeIn * fadeOut)));
		double breath = (Math.sin(life * Math.PI * 5) + 1d) / 2d;

		// A quiet sunburst sits behind the companion instead of filling the overlay.
		graphics.setStroke(new BasicStroke(Math.max(1f, (float) (1.25 * scale))));
		for (int ray = 0; ray < 12; ray++)
		{
			double angle = Math.PI * 2 * ray / 12d - Math.PI / 2d;
			double inner = (28 + breath * 3) * scale;
			double outer = (42 + breath * 7 + (ray % 2) * 6) * scale;
			graphics.setColor(new Color(0xFF, 0xE5, 0x91, alpha / 2));
			graphics.drawLine(centreX + (int) Math.round(Math.cos(angle) * inner),
				centreY + (int) Math.round(Math.sin(angle) * inner),
				centreX + (int) Math.round(Math.cos(angle) * outer),
				centreY + (int) Math.round(Math.sin(angle) * outer));
		}

		for (int ring = 0; ring < 2; ring++)
		{
			double phase = (life * 1.15 + ring * 0.48) % 1d;
			int ringAlpha = Math.max(0, (int) Math.round(120 * (1d - phase) * fadeOut));
			int radius = (int) Math.round((28 + phase * 34) * scale);
			graphics.setColor(new Color(0xFF, 0xF2, 0xC1, ringAlpha));
			graphics.drawOval(centreX - radius, centreY - radius, radius * 2, radius * 2);
		}

		// A handful of white-gold motes rise slowly through the halo.
		for (int i = 0; i < 12; i++)
		{
			double phase = (life * 0.9 + i * 0.079) % 1d;
			int moteAlpha = Math.max(0, (int) Math.round(190 * (1d - phase) * fadeOut));
			int px = centreX + (int) Math.round(Math.sin(i * 2.31) * width * 0.26);
			int py = y + height - (int) Math.round(phase * height * 0.88);
			int size = Math.max(2, (int) Math.round((2 + i % 2) * scale));
			graphics.setColor(new Color(0xFF, 0xF5, 0xD6, moteAlpha));
			graphics.fillOval(px, py, size, size);
		}
		graphics.setStroke(oldStroke);
	}
}

package com.gieligotchi.ui;

import com.gieligotchi.model.CompanionInstance;
import com.gieligotchi.service.LevelCurve;
import java.util.Objects;

/** Converts any level jump from one XP award into exactly one visual celebration. */
final class CompanionLevelTracker
{
	private String companionId;
	private int level = -1;

	CompanionEffectController.Effect observe(CompanionInstance companion)
	{
		if (companion == null)
		{
			companionId = null;
			level = -1;
			return null;
		}
		String currentId = companion.getInstanceId();
		if (currentId == null) { currentId = companion.getSpeciesId() + ":" + companion.getHatchedAt(); }
		int currentLevel = LevelCurve.levelFor(companion);
		if (!Objects.equals(companionId, currentId))
		{
			companionId = currentId;
			level = currentLevel;
			return null;
		}
		int previousLevel = level;
		level = currentLevel;
		if (currentLevel <= previousLevel) { return null; }
		return currentLevel >= 99 && previousLevel < 99
			? CompanionEffectController.Effect.MAX_LEVEL
			: CompanionEffectController.Effect.LEVEL_UP;
	}
}

package com.gieligotchi.ui;

import com.gieligotchi.GieligotchiConfig;
import com.gieligotchi.model.CompanionInstance;
import com.gieligotchi.model.EggState;
import com.gieligotchi.model.ProfileState;
import com.gieligotchi.model.HatchReceipt;
import com.gieligotchi.model.Toy;
import com.gieligotchi.service.GieligotchiStateService;
import com.gieligotchi.service.LevelCurve;
import com.gieligotchi.service.PetCatalogue;
import java.awt.Color;
import java.awt.BasicStroke;
import java.awt.AlphaComposite;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

@Singleton
public class GieligotchiOverlay extends Overlay
{
	private final GieligotchiStateService stateService;
	private final GieligotchiConfig config;
	private final HatchAnimationController hatchAnimation;
	private final PetCatalogue catalogue;
	private final CompanionEffectController effects;
	private volatile boolean hovered;

	@Inject
	public GieligotchiOverlay(GieligotchiStateService stateService, GieligotchiConfig config,
		HatchAnimationController hatchAnimation, PetCatalogue catalogue, CompanionEffectController effects)
	{
		this.stateService = stateService;
		this.config = config;
		this.hatchAnimation = hatchAnimation;
		this.catalogue = catalogue;
		this.effects = effects;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(OverlayPriority.MED);
		setMovable(false);
	}

	public void syncMovement() { setMovable(config.unlockOverlay()); }
	public void setHovered(boolean hovered) { this.hovered = hovered; }

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay()) { return null; }
		ProfileState state = stateService.getState();
		if (state == null) { return null; }
		// The former 75% presentation is now the canonical 100% size.
		double scale = config.overlayScale() / 100d * 0.75d;
		double textScale = Math.max(1d, Math.min(1.4d, config.textScale() / 100d));
		if (hatchAnimation.isCeremonyActive()) { return renderCeremony(graphics, state, scale); }
		boolean revealProgress = hovered;
		int visualWidth = Math.max(80, (int) Math.round(132 * scale));
		EggState egg = state.getActiveEgg();
		CompanionInstance companion = state.getActiveCompanion();
		BufferedImage sprite = egg != null ? hatchAnimation.eggImage(egg, config.reducedMotion())
			: companion != null ? SpriteAssets.companion(companion) : null;
		int artSize = Math.min(visualWidth - 12, (int) Math.round(118 * scale));
		int barHeight = Math.max(8, (int) Math.round(10 * scale));
		int barY = 5 + artSize + Math.max(2, (int) Math.round(3 * scale));
		int baseHeight = barY + barHeight + Math.max(5, (int) Math.round(5 * scale));
		int infoWidth = hovered && companion != null
			? Math.max(220, (int) Math.round(210 * scale * textScale)) : 0;
		int width = visualWidth + infoWidth;
		int height = baseHeight;
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		graphics.setColor(new Color(18, 20, 18, 245));
		graphics.fill(new RoundRectangle2D.Float(0, 0, width, height, 14, 14));
		graphics.setColor(companion != null && companion.isLegacy() ? new Color(242, 196, 90, 245)
			: companion != null && companion.getAffectionHearts() >= 60 ? new Color(219, 133, 169, 240)
			: new Color(118, 106, 72, 230));
		graphics.draw(new RoundRectangle2D.Float(1, 1, width - 3, height - 3, 14, 14));
		BufferedImage backdrop = config.showBackdropInOverlay()
			? SpriteAssets.backdrop(state.getEquippedBackdrop().getAssetId()) : null;
		if (backdrop != null)
		{
			int backdropX = (visualWidth - artSize) / 2;
			Shape oldClip = graphics.getClip();
			graphics.clip(new RoundRectangle2D.Float(backdropX, 5, artSize, artSize, 8, 8));
			SpriteAssets.drawNearest(graphics, backdrop, backdropX, 5, artSize, artSize);
			graphics.setColor(new Color(0, 0, 0, 22));
			graphics.fillRect(backdropX, 5, artSize, artSize);
			graphics.setClip(oldClip);
		}

		if (sprite == null) { return new Dimension(width, height); }
		boolean playing = companion != null && System.currentTimeMillis() - companion.getLastToyPlayedAt() < 4_000L;
		double idleSpeed = companion != null && companion.getPersonality() == com.gieligotchi.model.CompanionPersonality.PLAYFUL ? 260d : 360d;
		int motion = egg != null || config.reducedMotion() ? 0 : (int) Math.round(Math.sin(System.currentTimeMillis() / (playing ? 120d : idleSpeed)) * (playing ? 3 : 1) * scale);
		boolean legacyCeremony = companion != null && companion.isLegacy()
			&& System.currentTimeMillis() - companion.getLegacyAt() < 7_000L;
		if (legacyCeremony)
		{
			double pulse = (Math.sin(System.currentTimeMillis() / 100d) + 1d) / 2d;
			for (int ring = 3; ring >= 0; ring--)
			{
				int radius = (int) Math.round((25 + ring * 10 + pulse * 5) * scale);
				graphics.setColor(new Color(242, 196, 90, 14 + (3 - ring) * 12));
				graphics.fillOval(visualWidth / 2 - radius, 5 + artSize / 2 - radius, radius * 2, radius * 2);
			}
		}
		if (egg != null)
		{
			sprite = RiftglassGlow.apply(sprite, egg, config.reducedMotion());
			int eggSize = Math.max(1, (int) Math.round(artSize * 0.60d));
			int eggX = (visualWidth - eggSize) / 2;
			int eggY = 5 + (artSize - eggSize) / 2;
			SpriteAssets.drawNearestOpaqueShadowed(graphics, sprite, eggX, eggY, eggSize, eggSize,
				Math.max(1, (int) Math.round(2 * scale)), Math.max(1, (int) Math.round(2 * scale)));
		}
		else { SpriteAssets.drawNearestShadowed(graphics, sprite, (visualWidth - artSize) / 2,
			5 + motion, artSize, artSize, Math.max(1, (int) Math.round(2 * scale)), Math.max(1, (int) Math.round(2 * scale))); }
		Toy toy = companion != null && config.showToyInOverlay() ? state.getEquippedToy() : null;
		if (toy != null)
		{
			int toySize = Math.max(18, (int) Math.round(34 * scale));
			SpriteAssets.drawNearestOpaqueShadowed(graphics, SpriteAssets.toy(toy), visualWidth - toySize - 7,
				5 + artSize - toySize, toySize, toySize, 1, 2);
		}
		if (companion != null) { effects.render(graphics, 4, 5, visualWidth - 8, artSize, scale); }

		double progress;
		String label;
		if (egg != null)
		{
			progress = egg.getProgress();
			label = egg.isReady() ? "READY" : Math.round(progress * 100) + "%";
		}
		else
		{
			int level = LevelCurve.levelFor(companion);
			long floor = LevelCurve.xpForLevel(companion, level);
			long ceiling = level >= 99 ? floor : LevelCurve.xpForLevel(companion, level + 1);
			progress = level >= 99 ? 1d : (companion.getLifetimeXp() - floor) / (double) Math.max(1, ceiling - floor);
			label = "LVL " + level + " · " + Math.round(progress * 100) + "%";
		}
		int barX = 8;
		int barWidth = visualWidth - 16;
		graphics.setColor(new Color(45, 48, 42, 235));
		graphics.fillRoundRect(barX, barY, barWidth, barHeight, 6, 6);
		graphics.setColor(egg != null && egg.isReady() ? new Color(244, 183, 54) : new Color(116, 176, 102));
		graphics.fillRoundRect(barX, barY, (int) Math.round(barWidth * progress), barHeight, 6, 6);
		if (revealProgress)
		{
			graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD,
				Math.max(9, (int) Math.round(9 * scale * textScale))));
			FontMetrics metrics = graphics.getFontMetrics();
			int labelX = barX + Math.max(0, (barWidth - metrics.stringWidth(label)) / 2);
			int labelY = barY + (barHeight - metrics.getHeight()) / 2 + metrics.getAscent();
			graphics.setColor(new Color(0, 0, 0, 210));
			graphics.drawString(label, labelX + 1, labelY + 1);
			graphics.setColor(new Color(0xFFF4D2));
			graphics.drawString(label, labelX, labelY);
		}
		if (hovered && companion != null)
		{
			graphics.setColor(new Color(125, 111, 76, 235));
			graphics.drawLine(visualWidth, 7, visualWidth, height - 8);
			int textX = visualWidth + 8;
			int textY = Math.max(17, (int) Math.round(18 * scale));
			int fontSize = Math.max(12, (int) Math.round(13 * scale * textScale));
			graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, fontSize));
			com.gieligotchi.model.PetDefinition pet = catalogue.find(companion.getSpeciesId());
			String speciesName = pet == null ? "Companion" : pet.getName();
			drawReadableText(graphics, companion.getDisplayName(speciesName).toUpperCase(Locale.ENGLISH),
				textX, textY, new Color(0xF7D36D));
			graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, Math.max(11, fontSize - 1)));
			String personality = companion.getPersonality() == null ? "Undiscovered" : companion.getPersonality().getDisplayName();
			drawReadableText(graphics, "♥ " + companion.getAffectionHearts() + " " + companion.getRelationshipStage().getDisplayName()
				+ " · " + personality, textX, textY + fontSize + 4, new Color(0xF5F1E8));
			com.gieligotchi.model.HeartfeltWish heartfelt = companion.getHeartfeltWish();
			com.gieligotchi.model.CompanionWish wish = companion.getWish();
			if (heartfelt != null)
			{
				String wishLine = heartfelt.isApex() ? "✦ APEX HEARTFELT"
					: "♥ HEARTFELT";
				wishLine += !heartfelt.isAccepted() ? " · OFFERED"
					: heartfelt.isComplete() ? " · READY" : " · " + (heartfelt.getProgress() / 10) + "%";
				drawReadableText(graphics, wishLine, textX, textY + (fontSize + 4) * 2,
					heartfelt.isApex() ? new Color(0xE9D8F4) : new Color(0xFFE09A));
			}
			else if (wish != null)
			{
				String wishLine = "Wish " + wish.getProgress() + "/" + wish.getTarget()
					+ (wish.isComplete() ? " · READY" : "");
				drawReadableText(graphics, wishLine, textX, textY + (fontSize + 4) * 2, new Color(0xF5F1E8));
			}
			Toy equipped = state.getEquippedToy();
			drawReadableText(graphics, "Heartfelt fulfilled · " + companion.getHeartfeltCompletions(),
				textX, textY + (fontSize + 4) * 3, new Color(0xDDCB95));
			drawReadableText(graphics, equipped == null ? "No toy equipped" : equipped.getDisplayName(),
				textX, textY + (fontSize + 4) * 4, new Color(0xC8C8C8));
		}
		return new Dimension(width, height);
	}

	private void drawReadableText(Graphics2D graphics, String text, int x, int y, Color foreground)
	{
		graphics.setColor(new Color(0, 0, 0, 235));
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(foreground);
		graphics.drawString(text, x, y);
	}

	private Dimension renderCeremony(Graphics2D graphics, ProfileState state, double scale)
	{
		double textScale = Math.max(1d, Math.min(1.4d, config.textScale() / 100d));
		int width = Math.max(210, (int) Math.round(270 * scale));
		int height = Math.max(225, (int) Math.round(290 * scale));
		boolean reveal = hatchAnimation.isRevealing();
		EggState activeEgg = state.getActiveEgg();
		HatchReceipt receipt = reveal ? hatchAnimation.getLastReceipt() : null;
		Color borderColour = receipt == null ? new Color(0x756A52) : RarityColours.species(receipt.getSpeciesRarity());
		Color glowColour = receipt == null ? new Color(0xC8B989) : RarityColours.palette(receipt.getPalette());
		Composite oldComposite = graphics.getComposite();
		if (reveal) { graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, hatchAnimation.getRevealOpacity())); }
		double pulse = (Math.sin(System.currentTimeMillis() / 115d) + 1d) / 2d;
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		graphics.setColor(new Color(10, 11, 10, 238));
		graphics.fillRoundRect(0, 0, width, height, 22, 22);
		graphics.setStroke(new BasicStroke(3f));
		graphics.setColor(new Color(borderColour.getRed(), borderColour.getGreen(), borderColour.getBlue(), reveal ? 245 : 185));
		graphics.drawRoundRect(2, 2, width - 5, height - 5, 22, 22);

		int centreX = width / 2;
		int centreY = height / 2 + 3;
		if (reveal || activeEgg == null || activeEgg.getTier() != com.gieligotchi.model.EggTier.RIFTGLASS)
		{
			for (int ring = 5; ring >= 0; ring--)
			{
				int radius = 40 + ring * 13 + (int) Math.round(pulse * 7);
				int alpha = reveal ? 18 + (5 - ring) * 12 : 6 + (5 - ring) * 5;
				graphics.setColor(new Color(glowColour.getRed(), glowColour.getGreen(), glowColour.getBlue(), Math.min(120, alpha)));
				graphics.fillOval(centreX - radius, centreY - radius, radius * 2, radius * 2);
			}
		}

		BufferedImage image;
		if (reveal)
		{
			CompanionInstance companion = hatchAnimation.getLastCompanion();
			image = companion == null ? null : SpriteAssets.companion(companion);
		}
		else
		{
			image = activeEgg == null ? null : hatchAnimation.eggImage(activeEgg, config.reducedMotion());
			image = RiftglassGlow.apply(image, activeEgg, config.reducedMotion());
		}
		int artSize = reveal ? Math.min(width - 42, 168) : Math.min(width - 42, 172);
		if (image != null)
		{
			if (reveal) { SpriteAssets.drawNearestShadowed(graphics, image, centreX - artSize / 2,
				centreY - artSize / 2 - 6, artSize, artSize, 2, 3); }
			else { SpriteAssets.drawNearestOpaqueShadowed(graphics, image, centreX - artSize / 2,
				centreY - artSize / 2 - 6, artSize, artSize, 2, 3); }
		}
		graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, Math.max(14, (int) Math.round(14 * textScale))));
		graphics.setColor(new Color(0xF2C45A));
		com.gieligotchi.model.PetDefinition pet = receipt == null ? null : catalogue.find(receipt.getSpeciesId());
		String title = reveal && pet != null ? pet.getName().toUpperCase(Locale.ENGLISH) : reveal ? "A NEW COMPANION!" : "HATCHING...";
		FontMetrics titleMetrics = graphics.getFontMetrics();
		graphics.drawString(title, (width - titleMetrics.stringWidth(title)) / 2, 25);
		if (reveal && receipt != null)
		{
			graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, Math.max(10, (int) Math.round(10 * textScale))));
			graphics.setColor(Color.WHITE);
			String detail = receipt.getSpeciesRarity().getDisplayName().toUpperCase(Locale.ENGLISH)
				+ " · " + receipt.getPalette().getDisplayName().toUpperCase(Locale.ENGLISH);
			FontMetrics detailMetrics = graphics.getFontMetrics();
			graphics.drawString(detail, Math.max(7, (width - detailMetrics.stringWidth(detail)) / 2), height - 24);
			String chance = "EXACT HATCH: " + String.format(Locale.UK, "%.6f%%", receipt.getCombinedChance() * 100d);
			graphics.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, Math.max(9, (int) Math.round(9 * textScale))));
			FontMetrics chanceMetrics = graphics.getFontMetrics();
			graphics.drawString(chance, Math.max(7, (width - chanceMetrics.stringWidth(chance)) / 2), height - 10);
		}
		graphics.setComposite(oldComposite);
		return new Dimension(width, height);
	}
}

