final class RarityColours
{
	private RarityColours() {}

	static Color species(SpeciesRarity rarity)
	{
		switch (rarity)
		{
			case UNCOMMON: return new Color(0x62B85A);
			case RARE: return new Color(0x4AA7E8);
			case EPIC: return new Color(0xB06BE3);
			case LEGENDARY: return new Color(0xF2B53D);
			case COMMON:
			default: return new Color(0xD3D3D3);
		}
	}

	static Color palette(Palette palette)
	{
		switch (palette)
		{
			case COPPER: return new Color(0xD17A42);
			case MOSS: return new Color(0x79A94A);
			case AZURE: return new Color(0x4ABBE8);
			case VIOLET: return new Color(0x9A68DB);
			case ROSE: return new Color(0xE76DA9);
			case CRIMSON: return new Color(0xE34D4D);
			case FROST: return new Color(0xBCEEFF);
			case GILDED: return new Color(0xFFD057);
			case VOID: return new Color(0x7557C8);
			case OBSIDIAN: return new Color(0x747B86);
			case BASE:
			default: return new Color(0xF0E2B6);
		}
	}
}

package com.gieligotchi.ui;

import com.gieligotchi.model.EggState;
import com.gieligotchi.model.EggTier;
import java.awt.image.BufferedImage;

/** A pearl sheen clipped to the shell: it represents odds, never the eventual hatch rarity. */
final class RiftglassGlow
{
	private RiftglassGlow() {}

	static int band(EggState egg)
	{
		if (egg == null || egg.getTier() != EggTier.RIFTGLASS) { return 0; }
		return Math.min(3, Math.max(0, ((int) egg.getSpeciesOdds()[4] - 5) / 5));
	}

	static BufferedImage apply(BufferedImage source, EggState egg, boolean reducedMotion)
	{
		if (source == null || egg == null || egg.getTier() != EggTier.RIFTGLASS) { return source; }

		double strength = Math.max(0d, Math.min(1d, (egg.getSpeciesOdds()[4] - 5d) / 20d));
		double phase = reducedMotion ? 0.48d : (System.currentTimeMillis() % 3_200L) / 3_200d;
		// Travel beyond both edges so the shell has a calm pause between sweeps.
		double centre = -0.24d + phase * 1.48d;
		double width = 0.065d + strength * 0.035d;
		double peak = 0.30d + strength * 0.25d;
		int imageWidth = source.getWidth();
		int imageHeight = source.getHeight();
		BufferedImage result = new BufferedImage(imageWidth, imageHeight, BufferedImage.TYPE_INT_ARGB);

		for (int y = 0; y < imageHeight; y++)
		{
			for (int x = 0; x < imageWidth; x++)
			{
				int argb = source.getRGB(x, y);
				int alpha = argb >>> 24;
				if (alpha == 0) { continue; }
				double position = (x * 0.72d + y) / Math.max(1d, imageWidth * 0.72d + imageHeight);
				double distance = Math.abs(position - centre);
				double amount = distance >= width ? 0d : peak * Math.pow(1d - distance / width, 1.7d);
				int red = (argb >> 16) & 0xFF;
				int green = (argb >> 8) & 0xFF;
				int blue = argb & 0xFF;
				// Off-white with nearly equal channels keeps this pearlescent rather than rarity-coded.
				red = blend(red, 252, amount);
				green = blend(green, 252, amount);
				blue = blend(blue, 248, amount);
				result.setRGB(x, y, alpha << 24 | red << 16 | green << 8 | blue);
			}
		}
		return result;
	}

	private static int blend(int original, int pearl, double amount)
	{
		return Math.min(255, Math.max(0, (int) Math.round(original + (pearl - original) * amount)));
	}
}

package com.gieligotchi.ui;

import com.gieligotchi.model.ProfileState;
import com.gieligotchi.service.GieligotchiStateService;
import com.gieligotchi.service.SaveCodec;
import java.awt.Component;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.List;
import javax.swing.JFileChooser;
import javax.swing.JOptionPane;
import javax.swing.JTextArea;
import javax.swing.SwingWorker;
import javax.swing.filechooser.FileNameExtensionFilter;

/** File operations run off the EDT; imports are explicit, character-checked replacements. */
final class SaveManagerDialog
{
	private SaveManagerDialog() { }

	static void show(Component parent, GieligotchiStateService service)
	{
		String[] actions = {"Export", "Import", "Resolve conflict", "Recovery files", "Close"};
		JTextArea message = new JTextArea(service.getSyncStatus()
			+ "\n\nExport includes eggs, companions, collection, memories and goals."
			+ "\nImport replaces this character's progress; recovery copies are kept."
			+ "\nUse one client at a time. A queued save is not a confirmed cloud upload.", 7, 45);
		message.setEditable(false);
		message.setLineWrap(true);
		message.setWrapStyleWord(true);
		message.setOpaque(false);
		int action = JOptionPane.showOptionDialog(parent, message, "Gieligotchi · Save & sync",
			JOptionPane.DEFAULT_OPTION, JOptionPane.PLAIN_MESSAGE, null, actions, actions[4]);
		boolean recovery = action == 3;
		if (recovery) { action = 1; }
		ProfileState current = service.getState();
		if (action < 0 || action > 2) { return; }
		if (current == null) { error(parent, "Log into your OSRS character first."); return; }
		String character = current.getProfileKey();
		if (action == 2)
		{
			if (!service.hasSaveConflict()) { error(parent, "There is no save conflict to resolve."); return; }
			List<String> choices = service.getSaveChoices();
			String token = service.getConflictToken();
			Object selected = JOptionPane.showInputDialog(parent,
				"Choose the progress to keep. All alternatives are backed up first.\nProgress is not combined.",
				"Resolve save conflict", JOptionPane.WARNING_MESSAGE, null, choices.toArray(), choices.get(0));
			if (selected != null)
			{
				run(parent, () -> {
					service.resolveSave(choices.indexOf(selected), character, token);
					return "Choice saved. Recovery copies are available.";
				});
			}
			return;
		}
		JFileChooser chooser = new JFileChooser();
		if (recovery)
		{
			chooser.setCurrentDirectory(service.getSaveDirectory().toFile());
			chooser.setDialogTitle("Restore a recovery save");
		}
		chooser.setFileFilter(new FileNameExtensionFilter("Gieligotchi save (*.json)", "json"));
		if (action == 0)
		{
			chooser.setSelectedFile(new java.io.File("gieligotchi-" + character + "-" + System.currentTimeMillis() + ".json"));
			if (chooser.showSaveDialog(parent) != JFileChooser.APPROVE_OPTION) { return; }
			Path target = chooser.getSelectedFile().toPath();
			String snapshot = service.exportSave();
			run(parent, () -> {
				Files.writeString(target, snapshot, StandardCharsets.UTF_8, StandardOpenOption.CREATE_NEW);
				return "Save exported. Copy this file to your other device.\nKeep it private; it contains your character's progress.";
			});
		}
		else
		{
			if (chooser.showOpenDialog(parent) != JFileChooser.APPROVE_OPTION) { return; }
			Path source = chooser.getSelectedFile().toPath();
			if (JOptionPane.showConfirmDialog(parent, "Replace this character's progress with the selected save?\n"
				+ "This does not combine collections. A recovery copy will be kept.", "Import save",
				JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE) != JOptionPane.OK_OPTION) { return; }
			run(parent, () -> {
				if (Files.size(source) > SaveCodec.MAX_FILE_BYTES) { throw new IllegalArgumentException("Save file is too large."); }
				String text = Files.readString(source, StandardCharsets.UTF_8);
				service.importSave(text, character);
				return "Save imported. Your previous save is in Recovery files.";
			});
		}
	}

	private static void run(Component parent, java.util.concurrent.Callable<String> task)
	{
		new SwingWorker<String, Void>()
		{
			@Override protected String doInBackground() throws Exception { return task.call(); }
			@Override protected void done()
			{
				try { JOptionPane.showMessageDialog(parent, get(), "Gieligotchi saves", JOptionPane.INFORMATION_MESSAGE); }
				catch (Exception failure)
				{
					Throwable cause = failure.getCause() == null ? failure : failure.getCause();
					error(parent, cause instanceof java.nio.file.FileAlreadyExistsException
						? "That file already exists. Choose a new name to keep both backups." : cause.getMessage());
				}
			}
		}.execute();
	}

	private static void error(Component parent, String message)
	{
		JOptionPane.showMessageDialog(parent, message, "Gieligotchi saves", JOptionPane.WARNING_MESSAGE);
	}
}

package com.gieligotchi.ui;

import com.gieligotchi.model.CompanionInstance;
import com.gieligotchi.model.EggTier;
import com.gieligotchi.model.Toy;
import com.gieligotchi.service.LevelCurve;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.WeakHashMap;
import java.util.concurrent.ConcurrentHashMap;
import net.runelite.client.util.ImageUtil;

public final class SpriteAssets
{
	private static final Map<String, BufferedImage> CACHE = new ConcurrentHashMap<>();
	private static final Map<String, BufferedImage> MAX_LEVEL_COMPANIONS = new ConcurrentHashMap<>();
	private static final Map<Toy, BufferedImage> TOY_OVERRIDES = new ConcurrentHashMap<>();
	private static final Map<BufferedImage, BufferedImage> SHADOWS = Collections.synchronizedMap(new WeakHashMap<>());
	private static final Map<String, Point> PARTYHAT_ANCHORS = partyhatAnchors();
	private static volatile BufferedImage maxLevelPartyhat;

	private SpriteAssets() {}

	public static BufferedImage egg(EggTier tier)
	{
		String id = tier == EggTier.MEGA_RARE ? "mega-rare" : tier.name().toLowerCase();
		if (tier == EggTier.RIFTGLASS)
		{
			BufferedImage source = load("egg:" + id, "/com/gieligotchi/images/eggs/egg-" + id + ".png");
			return CACHE.computeIfAbsent("egg:riftglass:game-size", ignored ->
				resizeNearestOpaque(source, 96, 96));
		}
		return load("egg:" + id, "/com/gieligotchi/images/eggs/egg-" + id + ".png");
	}

	public static BufferedImage companion(CompanionInstance companion)
	{
		String assetKey = companion.getSpeciesId() + ":" + companion.getPalette().getAssetId();
		BufferedImage sprite = load("pet:" + assetKey,
			"/com/gieligotchi/images/pets/" + companion.getSpeciesId() + "/"
				+ companion.getPalette().getAssetId() + ".png");
		BufferedImage partyhat = maxLevelPartyhat;
		if (sprite == null || partyhat == null || LevelCurve.levelFor(companion) < 99) { return sprite; }
		return MAX_LEVEL_COMPANIONS.computeIfAbsent(assetKey,
			ignored -> decorateWithPartyhat(companion.getSpeciesId(), sprite, partyhat));
	}

	public static void setMaxLevelPartyhat(BufferedImage partyhat)
	{
		maxLevelPartyhat = partyhat;
		MAX_LEVEL_COMPANIONS.clear();
	}

	public static BufferedImage eggFrame(EggTier tier, int frame, String name)
	{
		if (tier == EggTier.RIFTGLASS) { return riftglassFrame(frame, 6); }
		String id = tier == EggTier.MEGA_RARE ? "mega_rare" : tier.name().toLowerCase();
		if (frame >= 5 && frame <= 8) { return stagedCrackFrame(id, frame, 64); }
		return load("egg-frame:" + id + ":" + frame,
			String.format("/com/gieligotchi/images/egg-animation/%s/%02d_%s.png", id, frame, name));
	}

	private static BufferedImage stagedCrackFrame(String id, int frame, int size)
	{
		BufferedImage sheet = load("egg-sheet:" + id,
			"/com/gieligotchi/images/egg-animation/" + id + "/cracking-sheet.png");
		return CACHE.computeIfAbsent("egg-frame:custom:" + id + ":" + frame, ignored ->
		{
			int index = frame - 5;
			int cellWidth = sheet.getWidth() / 2;
			int cellHeight = sheet.getHeight() / 2;
			BufferedImage cell = sheet.getSubimage((index % 2) * cellWidth,
				(index / 2) * cellHeight, cellWidth, cellHeight);
			return resizeNearestOpaque(removeFaintGenerationNoise(cell), size, size);
		});
	}

	private static BufferedImage removeFaintGenerationNoise(BufferedImage source)
	{
		BufferedImage cleaned = new BufferedImage(source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < source.getHeight(); y++)
		{
			for (int x = 0; x < source.getWidth(); x++)
			{
				int colour = source.getRGB(x, y);
				// The generated sheets have invisible alpha specks outside the artwork. If retained,
				// those specks double the measured bounds and make the first crack frame jump smaller.
				if ((colour >>> 24) >= 16) { cleaned.setRGB(x, y, colour); }
			}
		}
		return cleaned;
	}

	static BufferedImage riftglassIdleFrame(int frame, double progress)
	{
		int degrees = 2 + (int) Math.round(Math.max(0d, Math.min(1d, progress)) * 4d);
		return riftglassFrame(frame, degrees);
	}

	private static BufferedImage riftglassFrame(int frame, int wobbleDegrees)
	{
		if (frame < 0 || frame > 8) { return egg(EggTier.RIFTGLASS); }
		BufferedImage source = frame < 5 ? egg(EggTier.RIFTGLASS) : null;
		String key = "egg-frame:riftglass:" + frame + (frame < 5 ? ":" + wobbleDegrees : "");
		return CACHE.computeIfAbsent(key, ignored ->
		{
			if (frame < 5)
			{
				BufferedImage idle = new BufferedImage(96, 96, BufferedImage.TYPE_INT_ARGB);
				Graphics2D graphics = idle.createGraphics();
				// The renderer trims transparent bounds, so positional shifts disappear.
				// Tilt the shell itself for a wobble that survives that trimming.
				int tilt = frame == 1 ? -wobbleDegrees : frame == 3 ? wobbleDegrees : 0;
				graphics.rotate(Math.toRadians(tilt), 48, 48);
				drawNearestOpaque(graphics, source, 8, 8, 80, 80);
				graphics.dispose();
				return idle;
			}
			return stagedCrackFrame("riftglass", frame, 96);
		});
	}

	public static BufferedImage pet(String speciesId, String palette)
	{
		return load("pet:" + speciesId + ":" + palette,
			"/com/gieligotchi/images/pets/" + speciesId + "/" + palette + ".png");
	}

	public static BufferedImage backdrop(String backdropId)
	{
		if (backdropId == null || "classic".equals(backdropId)) { return null; }
		return load("backdrop:" + backdropId,
			"/com/gieligotchi/images/backdrops/" + backdropId + ".png");
	}

	public static BufferedImage toy(Toy toy)
	{
		if (toy == null) { return null; }
		return TOY_OVERRIDES.get(toy);
	}

	public static void setToyImage(Toy toy, BufferedImage image)
	{
		if (toy != null && image != null) { TOY_OVERRIDES.put(toy, image); }
	}

	public static BufferedImage composeRunePile(List<? extends BufferedImage> runes)
	{
		BufferedImage pile = new BufferedImage(128, 128, BufferedImage.TYPE_INT_ARGB);
		if (runes == null || runes.isEmpty()) { return pile; }
		Graphics2D graphics = pile.createGraphics();
		int[][] positions = {{18, 31}, {47, 25}, {76, 34}, {7, 64}, {38, 58}, {70, 66}};
		int[] sizes = {45, 48, 44, 49, 50, 47};
		for (int index = 0; index < runes.size() && index < positions.length; index++)
		{
			int size = sizes[index];
			drawNearestOpaque(graphics, runes.get(index), positions[index][0], positions[index][1], size, size - 3);
		}
		graphics.dispose();
		return pile;
	}

	public static void drawNearest(Graphics2D graphics, BufferedImage image, int x, int y, int width, int height)
	{
		if (image == null) { return; }
		Object old = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		graphics.drawImage(image, x, y, width, height, null);
		if (old != null) { graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, old); }
	}

	public static void drawNearestShadowed(Graphics2D graphics, BufferedImage image,
		int x, int y, int width, int height, int shadowX, int shadowY)
	{
		if (image == null) { return; }
		drawNearest(graphics, shadowFor(image), x + shadowX, y + shadowY, width, height);
		drawNearest(graphics, image, x, y, width, height);
	}

	public static void drawNearestOpaqueShadowed(Graphics2D graphics, BufferedImage image,
		int x, int y, int width, int height, int shadowX, int shadowY)
	{
		if (image == null) { return; }
		drawNearestOpaque(graphics, shadowFor(image), x + shadowX, y + shadowY, width, height);
		drawNearestOpaque(graphics, image, x, y, width, height);
	}

	public static BufferedImage resizeNearestShadowedOpaque(BufferedImage image, int width, int height)
	{
		if (image == null) { return null; }
		BufferedImage scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = scaled.createGraphics();
		int contentWidth = Math.max(1, width - 3);
		int contentHeight = Math.max(1, height - 4);
		drawNearestOpaque(graphics, shadowFor(image), 2, 3, contentWidth, contentHeight);
		drawNearestOpaque(graphics, image, 0, 0, contentWidth, contentHeight);
		graphics.dispose();
		return scaled;
	}

	private static BufferedImage shadowFor(BufferedImage image)
	{
		BufferedImage cached = SHADOWS.get(image);
		if (cached != null) { return cached; }
		BufferedImage shadow = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				int alpha = image.getRGB(x, y) >>> 24;
				shadow.setRGB(x, y, (Math.min(48, alpha / 4) << 24));
			}
		}
		SHADOWS.put(image, shadow);
		return shadow;
	}

	public static BufferedImage resizeNearest(BufferedImage image, int width, int height)
	{
		if (image == null) { return null; }
		BufferedImage scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = scaled.createGraphics();
		drawNearest(graphics, image, 0, 0, width, height);
		graphics.dispose();
		return scaled;
	}

	public static BufferedImage resizeNearestOpaque(BufferedImage image, int width, int height)
	{
		if (image == null) { return null; }
		BufferedImage scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = scaled.createGraphics();
		drawNearestOpaque(graphics, image, 0, 0, width, height);
		graphics.dispose();
		return scaled;
	}

	private static BufferedImage decorateWithPartyhat(String speciesId, BufferedImage sprite, BufferedImage partyhat)
	{
		BufferedImage decorated = new BufferedImage(sprite.getWidth(), sprite.getHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = decorated.createGraphics();
		int insetX = Math.max(2, sprite.getWidth() / 20);
		int insetTop = Math.max(5, sprite.getHeight() / 10);
		int scaledWidth = sprite.getWidth() - insetX * 2;
		int scaledHeight = sprite.getHeight() - insetTop - Math.max(2, sprite.getHeight() / 40);
		drawNearest(graphics, sprite, insetX, insetTop, scaledWidth, scaledHeight);

		int minX = sprite.getWidth(), minY = sprite.getHeight(), maxX = -1;
		for (int y = 0; y < sprite.getHeight(); y++)
		{
			for (int x = 0; x < sprite.getWidth(); x++)
			{
				if ((sprite.getRGB(x, y) >>> 24) != 0)
				{
					minX = Math.min(minX, x);
					minY = Math.min(minY, y);
					maxX = Math.max(maxX, x);
				}
			}
		}
		if (maxX >= minX)
		{
			Point sourceAnchor = PARTYHAT_ANCHORS.get(speciesId);
			if (sourceAnchor == null) { sourceAnchor = new Point((minX + maxX) / 2, minY + 18); }
			int anchorX = insetX + (int) Math.round(sourceAnchor.x * scaledWidth / (double) sprite.getWidth());
			int anchorY = insetTop + (int) Math.round(sourceAnchor.y * scaledHeight / (double) sprite.getHeight());
			int petWidth = Math.max(1, (maxX - minX + 1) * scaledWidth / sprite.getWidth());
			// Base the hat on the creature's visible scale, but keep it narrow enough to
			// read as headwear on wide silhouettes such as Kraken and the spider pets.
			int hatWidth = Math.max(18, Math.min(26, petWidth / 4));
			int hatHeight = Math.max(16, (int) Math.round(hatWidth * 0.86d));
			int hatX = Math.max(0, Math.min(sprite.getWidth() - hatWidth, anchorX - hatWidth / 2));
			int hatY = Math.max(0, Math.min(sprite.getHeight() - hatHeight, anchorY - hatHeight + 5));
			// Cache the companion-only shadow before adding the hat. Callers can still
			// shadow the companion normally without creating a second shadow under the hat.
			shadowFor(decorated);
			drawNearestOpaque(graphics, partyhat, hatX, hatY, hatWidth, hatHeight);
		}
		graphics.dispose();
		return decorated;
	}

	private static Map<String, Point> partyhatAnchors()
	{
		Map<String, Point> anchors = new HashMap<>();
		putAnchors(anchors,
			"abyssal_orphan,65,25;abyssal_protector,64,22;aggy,75,26;baby_chinchompa,45,45;baby_mole,45,70;baron,70,36;beaver,42,74;beef,46,55;bloodhound,50,61;bran,68,30;butch,77,35;callisto_cub,45,70;chompy_chick,50,46;dom,64,52;giant_squirrel,49,75;gull,42,53;hellpuppy,43,60;herbi,37,70;heron,50,30;huberte,67,40;ikkle_hydra,63,25;jal_nib_rek,50,62;kalphite_princess,78,40;lil_creator,70,30;lil_zik,64,54;lilviathan,58,58;little_nightmare,64,52;maggot_marquess,45,28;moxi,65,34;mr_mcgroot,45,50;muphin,50,50;nexling,70,25;nid,64,60;noon,61,53;olmlet,59,48;pet_chaos_elemental,64,30");
		putAnchors(anchors,
			"pet_dagannoth_prime,47,48;pet_dagannoth_rex,55,47;pet_dagannoth_supreme,50,50;pet_dark_core,65,55;pet_general_graardor,66,35;pet_kraken,65,54;pet_kreearra,58,50;pet_kril_tsutsaroth,62,36;pet_penance_queen,66,53;pet_smoke_devil,64,35;pet_snakeling,71,36;pet_zilyana,64,33;phoenix,45,50;prince_black_dragon,45,64;quetzin,45,58;rift_guardian,64,29;rock_golem,64,35;rocky,43,60;scorpias_offspring,77,66;scurry,40,58;skotos,64,40;smol_heredit,65,28;smolcano,64,34;soup,47,69;sraracha,63,52;tangleroot,61,36;tiny_tempor,64,65;tumekens_guardian,65,29;tzrek_jad,45,55;venenatis_spiderling,64,58;vetion_jr,65,30;vorki,42,62;wisp,64,35;yami,64,34;youngllef,48,53");
		return anchors;
	}

	private static void putAnchors(Map<String, Point> anchors, String definitions)
	{
		for (String definition : definitions.split(";"))
		{
			String[] parts = definition.split(",");
			anchors.put(parts[0], new Point(Integer.parseInt(parts[1]), Integer.parseInt(parts[2])));
		}
	}

	/** Draw only the sprite's visible bounds, aspect-fitted inside the destination. */
	public static void drawNearestOpaque(Graphics2D graphics, BufferedImage image,
		int x, int y, int width, int height)
	{
		if (image == null) { return; }
		int minX = image.getWidth(), minY = image.getHeight(), maxX = -1, maxY = -1;
		for (int sourceY = 0; sourceY < image.getHeight(); sourceY++)
		{
			for (int sourceX = 0; sourceX < image.getWidth(); sourceX++)
			{
				if ((image.getRGB(sourceX, sourceY) >>> 24) != 0)
				{
					minX = Math.min(minX, sourceX); minY = Math.min(minY, sourceY);
					maxX = Math.max(maxX, sourceX); maxY = Math.max(maxY, sourceY);
				}
			}
		}
		if (maxX < minX || maxY < minY) { return; }
		int sourceWidth = maxX - minX + 1, sourceHeight = maxY - minY + 1;
		double factor = Math.min(width / (double) sourceWidth, height / (double) sourceHeight);
		int drawWidth = Math.max(1, (int) Math.round(sourceWidth * factor));
		int drawHeight = Math.max(1, (int) Math.round(sourceHeight * factor));
		drawNearestRegion(graphics, image, minX, minY, sourceWidth, sourceHeight,
			x + (width - drawWidth) / 2, y + (height - drawHeight) / 2, drawWidth, drawHeight);
	}

	public static void drawNearestRegion(Graphics2D graphics, BufferedImage image,
		int sourceX, int sourceY, int sourceWidth, int sourceHeight,
		int x, int y, int width, int height)
	{
		if (image == null) { return; }
		Object old = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		graphics.drawImage(image, x, y, x + width, y + height,
			sourceX, sourceY, sourceX + sourceWidth, sourceY + sourceHeight, null);
		if (old != null) { graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, old); }
	}

	private static BufferedImage load(String key, String resource)
	{
		return CACHE.computeIfAbsent(key, ignored -> ImageUtil.loadImageResource(SpriteAssets.class, resource));
	}
}

package com.gieligotchi;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.prefs.AbstractPreferences;
import java.util.prefs.BackingStoreException;
import java.util.prefs.Preferences;
import java.util.prefs.PreferencesFactory;

/** Development-only in-memory preferences, keeping the isolated client out of the Windows registry. */
public final class DevPreferencesFactory implements PreferencesFactory
{
	private final Preferences users = new MemoryNode(null, "");
	private final Preferences system = new MemoryNode(null, "");
	@Override public Preferences userRoot() { return users; }
	@Override public Preferences systemRoot() { return system; }

	private static final class MemoryNode extends AbstractPreferences
	{
		private final Map<String, String> values = new ConcurrentHashMap<>();
		private final Map<String, MemoryNode> nodes = new ConcurrentHashMap<>();
		private MemoryNode(AbstractPreferences parent, String name) { super(parent, name); }
		@Override protected void putSpi(String key, String value) { values.put(key, value); }
		@Override protected String getSpi(String key) { return values.get(key); }
		@Override protected void removeSpi(String key) { values.remove(key); }
		@Override protected void removeNodeSpi() { values.clear(); nodes.clear(); }
		@Override protected String[] keysSpi() { return values.keySet().toArray(new String[0]); }
		@Override protected String[] childrenNamesSpi() { return nodes.keySet().toArray(new String[0]); }
		@Override protected AbstractPreferences childSpi(String name) { return nodes.computeIfAbsent(name, key -> new MemoryNode(this, key)); }
		@Override protected void syncSpi() throws BackingStoreException { }
		@Override protected void flushSpi() throws BackingStoreException { }
	}
}

